 const SOURCE={"chain":{"subject":"ગણિત (Mathematics)","chapter_title":"સાંકળનો નિયમ (Chain Rule / MDH Formula)","source_pdf":"સાંકળનો નિયમ .pdf","total_questions_count":34,"concept_notes":{"title":"સાંકળનો નિયમ (Chain Rule) - થીયરી, સૂત્રો અને શોર્ટકટ્સ","mdh_formula":{"main_formula":"(M1 * D1 * H1) / W1 = (M2 * D2 * H2) / W2","cross_multiplication_shorthand":"M1 * D1 * H1 * W2 = M2 * D2 * H2 * W1","variables_explanation":{"M":"કામ કરનારની સંખ્યા (માણસો, કારીગરો, મશીનો, પ્રાણીઓ વગેરે)","D":"દિવસોની સંખ્યા (Days)","H":"દરરોજના કામના કલાકો (Hours per day)","W":"કરેલું કુલ કામ / ઉત્પાદન / લંબાઈ / ક્ષેત્રફળ / વૃક્ષો / ઉત્તરવહીઓ / પગાર વગેરે (Work/Output/Wages)"}},"types_breakdown":[{"type_number":1,"type_name":"સાદો સાંકળનો નિયમ (Direct MDH Rule)","description":"જ્યારે કામ અથવા વ્યક્તિઓની સંખ્યા બદલાય ત્યારે દ્વિપદી સરખામણી કરવા માટે MDH સૂત્રનો સીધો ઉપયોગ કરવો."},{"type_number":2,"type_name":"રાશન/ખોરાક અને સૈનિકોના કેમ્પના કોયડા (Ration / Camp Food / Left or Joined Problems)","description":"જ્યારે અમુક દિવસો પછી નવા માણસો ઉમેરાય અથવા અમુક માણસો છોડીને જાય ત્યારે બાકીના દિવસો શોધવાનું સૂત્ર.","formula":"બાકીના દિવસો = (શરૂઆતના માણસો * બાકી રહેલા દિવસો) / અંતે રહેલા માણસો"}]},"questions":[{"question_number":1,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - સાદો સાંકળનો નિયમ","question_text":"5 બિલાડી 5 ઉંદર 5 દિવસમાં ખાય છે તો 1 બિલાડી 1 ઉંદર કેટલા દિવસમાં ખાશે?","options":{"A":"1","B":"5","C":"10","D":"50"},"correct_answer":"B","explanation":"MDH સૂત્ર મુજબ: (M1 * D1) / W1 = (M2 * D2) / W2\nઅહીં M1 = 5 બિલાડી, D1 = 5 દિવસ, W1 = 5 ઉંદર (કામ).\nતથા M2 = 1 બિલાડી, W2 = 1 ઉંદર.\n(5 * 5) / 5 = (1 * D2) / 1\n5 = D2\nતેથી 1 બિલાડી 1 ઉંદર 5 દિવસમાં ખાશે. સાચો વિકલ્પ (B) છે."},{"question_number":2,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - સાદો સાંકળનો નિયમ","question_text":"જો 10 વ્યક્તિ 10 કામ 10 દિવસમાં કરે તો 5 વ્યક્તિ 5 કામ કેટલા દિવસ માં કરે ?","options":{"A":"1","B":"5","C":"10","D":"50"},"correct_answer":"C","explanation":"(M1 * D1) / W1 = (M2 * D2) / W2\n(10 * 10) / 10 = (5 * D2) / 5\n10 = D2\nતેથી 5 વ્યક્તિ 5 કામ 10 દિવસમાં કરશે. સાચો વિકલ્પ (C) છે."},{"question_number":3,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - સાદો સાંકળનો નિયમ","question_text":"એક કામ 30 મજુર 20 દિવસ માં પૂરૂ કરે તો તે કામ 25 મજુર કેટલા દિવસ માં પૂરૂ કરે.","options":{"A":"21","B":"25","C":"24","D":"18"},"correct_answer":"C","explanation":"M1 * D1 = M2 * D2 (અહીં કામ સમાન છે)\n30 * 20 = 25 * D2\n600 = 25 * D2\nD2 = 600 / 25 = 24 દિવસ.\nસાચો વિકલ્પ (C) છે."},{"question_number":4,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - સાદો સાંકળનો નિયમ","question_text":"જે કામ 12 માણસો 9 દિવસ માં પૂરૂ કરે છે તો તે જ કામ 18 માણસો કેટલા દિવસ માં પૂરૂ કરે.","options":{"A":"3","B":"6","C":"9","D":"12"},"correct_answer":"B","explanation":"M1 * D1 = M2 * D2\n12 * 9 = 18 * D2\n108 = 18 * D2\nD2 = 108 / 18 = 6 દિવસ.\nસાચો વિકલ્પ (B) છે."},{"question_number":5,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - સાદો સાંકળનો નિયમ","question_text":"15 માણસો ખેતીનો પાક 30 દિવસમાં કાપે છે તો 12 માણસો આ પાકને કેટલા દિવસમાં કાપે.","options":{"A":"37.5","B":"40","C":"45","D":"30"},"correct_answer":"A","explanation":"M1 * D1 = M2 * D2\n15 * 30 = 12 * D2\n450 = 12 * D2\nD2 = 450 / 12 = 37.5 દિવસ.\nસાચો વિકલ્પ (A) છે."},{"question_number":6,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - સાદો સાંકળનો નિયમ","question_text":"40 વ્યક્તિઓ પાસે 30 દિવસ ચાલે તેટલું અનાજ છે તો 52 વ્યક્તિઓને આ અનાજનો જથ્થો આશરે કેટલા દિવસ ચાલશે.","options":{"A":"20","B":"23","C":"25","D":"18"},"correct_answer":"B","explanation":"M1 * D1 = M2 * D2\n40 * 30 = 52 * D2\n1200 = 52 * D2\nD2 = 1200 / 52 = 300 / 13 ≈ 23.07 દિવસ (આશરે 23 દિવસ).\nસાચો વિકલ્પ (B) છે."},{"question_number":7,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - સાદો સાંકળનો નિયમ (મશીન ઉત્પાદન)","question_text":"જો 15 કારીગર અમુક પ્રકારના 18 મશીન 24 દિવસમાં બનાવે તો 40 કારીગર તેવા જ 22 મશીન કેટલા દિવસમાં બનાવી શકે.","options":{"A":"11","B":"22","C":"33","D":"44"},"correct_answer":"A","explanation":"(M1 * D1) / W1 = (M2 * D2) / W2\n(15 * 24) / 18 = (40 * D2) / 22\n360 / 18 = (40 * D2) / 22\n20 = (40 * D2) / 22\n20 * 22 = 40 * D2\n440 = 40 * D2 => D2 = 11 દિવસ.\nસાચો વિકલ્પ (A) છે."},{"question_number":8,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - સાદો સાંકળનો નિયમ (દીવાલ ચણવી)","question_text":"7 મજૂરો 8 દિવસમાં 42 મીટર ની દીવાલ ચણે છે તો કેટલા મજૂરો 6 દિવસમાં 45 મીટરની દીવાલ ચણી શકે.","options":{"A":"12","B":"10","C":"9","D":"8"},"correct_answer":"B","explanation":"(M1 * D1) / W1 = (M2 * D2) / W2\n(7 * 8) / 42 = (M2 * 6) / 45\n56 / 42 = (6 * M2) / 45\n4/3 = (6 * M2) / 45\n4 * 45 / 3 = 6 * M2\n60 = 6 * M2 => M2 = 10 મજૂરો.\nસાચો વિકલ્પ (B) છે."},{"question_number":9,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - MDH કલાક અને વૃક્ષો વાવવા","question_text":"40 માણસો 60 વૃક્ષો 8 કલાકમાં વાવી શકે તો 32 માણસો 12 કલાકમાં કેટલા વૃક્ષો વાવી શકે.","options":{"A":"72","B":"46","C":"85","D":"56"},"correct_answer":"A","explanation":"(M1 * H1) / W1 = (M2 * H2) / W2\n(40 * 8) / 60 = (32 * 12) / W2\n320 / 60 = 384 / W2\n16 / 3 = 384 / W2\nW2 = (384 * 3) / 16 = 24 * 3 = 72 વૃક્ષો.\nસાચો વિકલ્પ (A) છે."},{"question_number":10,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - પગાર અને મહેનતાણું","question_text":"6 વ્યક્તિઓનો 15 દિવસનો પગાર રૂ 2100 છે તો 9 વ્યક્તિઓનો 12 દિવસ નો પગાર કેટલો થાય.","options":{"A":"2100","B":"2520","C":"2430","D":"2250"},"correct_answer":"B","explanation":"(M1 * D1) / W1 = (M2 * D2) / W2 (અહીં W = કુલ પગાર)\n(6 * 15) / 2100 = (9 * 12) / W2\n90 / 2100 = 108 / W2\n3 / 70 = 108 / W2\nW2 = (108 * 70) / 3 = 36 * 70 = રૂ. 2520.\nસાચો વિકલ્પ (B) છે."},{"question_number":11,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - પુસ્તકો બાંધવાનું કામ","question_text":"18 કામદારો 10 દિવસમાં 900 પુસ્તકો બાંધે છે તો 12 દિવસમાં 660 પુસ્તકો બાંધવા કેટલા કામદાર જોઈએ.","options":{"A":"10","B":"11","C":"12","D":"18"},"correct_answer":"B","explanation":"(M1 * D1) / W1 = (M2 * D2) / W2\n(18 * 10) / 900 = (M2 * 12) / 660\n180 / 900 = 12 * M2 / 660\n1/5 = 12 * M2 / 660\n660 / 5 = 12 * M2\n132 = 12 * M2 => M2 = 11 કામદારો.\nસાચો વિકલ્પ (B) છે."},{"question_number":12,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - કમાણી અને દિવસો","question_text":"જો 24 વ્યક્તિઓ 8 દિવસ કામ કરે છે તો તેઓ કુલ રૂપિયા 9600 કમાય છે તેવો પૈકી 12 વ્યક્તિઓ 12 દિવસ કામ કરે તો તેઓની કુલ કમાણી કેટલા રૂપિયા થાય.","options":{"A":"6400","B":"7200","C":"7600","D":"8000"},"correct_answer":"B","explanation":"(M1 * D1) / W1 = (M2 * D2) / W2\n(24 * 8) / 9600 = (12 * 12) / W2\n192 / 9600 = 144 / W2\n1 / 50 = 144 / W2 => W2 = 144 * 50 = રૂ. 7200.\nસાચો વિકલ્પ (B) છે."},{"question_number":13,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - દૈનિક કલાકો અને માણસો વધારવા","question_text":"પાંચ માણસો સાત કલાક પ્રતિ દિવસ કામ કરીને એક કેસલિસ્ટ આઠ દિવસમાં બનાવી શકે છે જો આ કામ ચાર દિવસમાં પૂરૂ કરવા વધુ બે વ્યક્તિ મદદ કરે તો તે લોકો ને પ્રતિ દિવસ કેટલા કલાક કામ કરવું પડે.","options":{"A":"10","B":"20","C":"30","D":"40"},"correct_answer":"A","explanation":"M1 * D1 * H1 = M2 * D2 * H2\nઅહીં M1 = 5, H1 = 7, D1 = 8\nM2 = 5 + 2 = 7 માણસો, D2 = 4 દિવસ, H2 = ?\n5 * 8 * 7 = 7 * 4 * H2\n280 = 28 * H2 => H2 = 10 કલાક.\nસાચો વિકલ્પ (A) છે."},{"question_number":14,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - રસ્તાનું સમારકામ (MDH)","question_text":"એક રસ્તાનું સમારકામ કરતા 39 માણસોને દિવસના 5 કલાક પ્રમાણે 12 દિવસ લાગે છે જો 30 માણસો રોજના 6 કલાક પ્રમાણે કામ કરે તો તે કામ પૂરૂ કરતા કેટલા દિવસ લાગે.","options":{"A":"12","B":"13","C":"14","D":"15"},"correct_answer":"B","explanation":"M1 * D1 * H1 = M2 * D2 * H2\n39 * 12 * 5 = 30 * D2 * 6\n2340 = 180 * D2\nD2 = 2340 / 180 = 13 દિવસ.\nસાચો વિકલ્પ (B) છે."},{"question_number":15,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - દરરોજના કલાક અને દિવસો","question_text":"12 માણસો દરરોજ 9 કલાક કામ કરે તો તે કામ 20 દિવસમાં પૂરૂ થાય તે જ કામ 10 માણસો દરરોજ 12 કલાક કરીને કેટલા દિવસમાં પૂરૂ કરશે.","options":{"A":"18","B":"20","C":"16","D":"15"},"correct_answer":"A","explanation":"M1 * D1 * H1 = M2 * D2 * H2\n12 * 20 * 9 = 10 * D2 * 12\n2160 = 120 * D2\nD2 = 2160 / 120 = 18 દિવસ.\nસાચો વિકલ્પ (A) છે."},{"question_number":16,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - વધારાના કારીગરોની સંખ્યા","question_text":"15 કારીગરો દરરોજ 8 કલાક કામ કરીને એક દિવાલ 20 દિવસમાં પૂરી કરે છે તો તે જ દિવાલને દરરોજ 6 કલાક કામ કરીને 16 દિવસમાં પૂરી કરવા કેટલા કારીગરો વધારવા પડશે.","options":{"A":"10","B":"5","C":"15","D":"25"},"correct_answer":"A","explanation":"M1 * D1 * H1 = M2 * D2 * H2\n15 * 20 * 8 = M2 * 16 * 6\n2400 = 96 * M2\nM2 = 2400 / 96 = 25 કારીગરો.\nવધારવાના કારીગરો = M2 - M1 = 25 - 15 = 10 કારીગરો.\nસાચો વિકલ્પ (A) છે."},{"question_number":17,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - મશીન બોટલ ઉત્પાદન","question_text":"એક કારખાનામાં સમાન ક્ષમતાથી ચાલતાં 4 મશીન 1 મિનિટમાં 300 નંગ બાટલીઓ બનાવે છે તો 12 મશીન 3 મિનિટમાં કેટલી બનાવી શકે.","options":{"A":"2400","B":"2700","C":"3000","D":"2100"},"correct_answer":"B","explanation":"(M1 * T1) / W1 = (M2 * T2) / W2\n(4 * 1) / 300 = (12 * 3) / W2\n4 / 300 = 36 / W2\n4 * W2 = 300 * 36 = 10800\nW2 = 10800 / 4 = 2700 બાટલીઓ.\nસાચો વિકલ્પ (B) છે."},{"question_number":18,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - વધારાના પાણીના પંપ","question_text":"20 સરખી ક્ષમતાવાળા પાણીના પંપ 6 દિવસમાં એક ટાંકી પૂર્ણ રીતે ભરી શકે છે જો આ ટાંકી 4 દિવસમાં ભરવી હોય તો કેટલા વધારાના પંપ ની જરૂર પડે.","options":{"A":"10","B":"20","C":"30","D":"40"},"correct_answer":"A","explanation":"M1 * D1 = M2 * D2\n20 * 6 = M2 * 4\n120 = 4 * M2 => M2 = 30 પંપ.\nવધારાના પંપ = 30 - 20 = 10 પંપ.\nસાચો વિકલ્પ (A) છે."},{"question_number":19,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - મજૂરોનો કાપ મૂકવો","question_text":"40 મજૂરો એક કામ 28 દિવસમાં પૂરૂ કરે છે જો એ કામ 35 દિવસમાં પૂરૂ કરવાનું હોય તો કેટલા મજૂરોનો કાપ મૂકવો જોઈએ.","options":{"A":"10","B":"32","C":"8","D":"16"},"correct_answer":"C","explanation":"M1 * D1 = M2 * D2\n40 * 28 = M2 * 35\n1120 = 35 * M2 => M2 = 32 મજૂરો.\nકાપ મૂકવાનો મજૂરો = 40 - 32 = 8 મજૂરો.\nસાચો વિકલ્પ (C) છે."},{"question_number":20,"source":"સાંકળનો નિયમ .pdf","topic":"Type 1 - પરીક્ષકો અને ઉત્તરવહીઓ","question_text":"12 પરીક્ષકો રોજના 16 કલાક કામ કરી 18 દિવસમાં 24000 ઉત્તરવહીઓ તપાસે છે તો 24 પરીક્ષકો રોજના 6 કલાક કામ કરી 36 દિવસમાં કેટલી ઉત્તરવહીઓ તપાસશે.","options":{"A":"36000","B":"42000","C":"30000","D":"45000"},"correct_answer":"A","explanation":"(M1 * D1 * H1) / W1 = (M2 * D2 * H2) / W2\n(12 * 18 * 16) / 24000 = (24 * 36 * 6) / W2\n3456 / 24000 = 5184 / W2\n0.144 = 5184 / W2 => W2 = 5184 / 0.144 = 36000 ઉત્તરવહીઓ.\nસાચો વિકલ્પ (A) છે."},{"question_number":21,"source":"સાંકળનો નિયમ .pdf","topic":"CCE 2023 PYQ - ઘરનું રંગકામ","question_text":"આઠ લોકો 8 દિવસમાં એક ઘરને રંગકામ કરી શકે છે. 4 દિવસમાં ઘરને રંગવા માટે કેટલા લોકોની જરૂર પડશો? (CCE 2023)","options":{"A":"18 પેઇન્ટર્સ","B":"16 પેઇન્ટર્સ","C":"12 પેઇન્ટર્સ","D":"14 પેઇન્ટર્સ"},"correct_answer":"B","explanation":"M1 * D1 = M2 * D2\n8 * 8 = M2 * 4\n64 = 4 * M2 => M2 = 16 પેઇન્ટર્સ.\nસાચો વિકલ્પ (B) છે."},{"question_number":22,"source":"સાંકળનો નિયમ .pdf","topic":"CCE 2023 PYQ - ગેરહાજર પુરુષો","question_text":"ચોક્કસ સંખ્યામાં પુરુષો 20 દિવસમાં એક કામ કરવા સંમત થયા. 5 પુરુષો કામ માટે ન આવ્યા. અન્ય પુરુષોએ 30 દિવસમાં કામ પૂર્ણ કર્યું. મૂળ રીતે કામ કરવા માટે સંમત થયેલા પુરુષોની સંખ્યા શોધો? (CCE 2023)","options":{"A":"20","B":"23","C":"25","D":"15"},"correct_answer":"D","explanation":"ધારો કે શરૂઆતમાં પુરુષોની સંખ્યા x હતી.\nx * 20 = (x - 5) * 30\n20x = 30x - 150\n10x = 150 => x = 15 પુરુષો.\nસાચો વિકલ્પ (D) છે."},{"question_number":23,"source":"સાંકળનો નિયમ .pdf","topic":"CCE 2023 PYQ - માળીઓ અને વૃક્ષો","question_text":"5 માળીઓ 5 કલાકમાં 25 વૃક્ષો વાવી શકે છે. 20 કલાકમાં 100 વૃક્ષો વાવવા માટે કેટલા માળીઓની જરૂર છે? (CCE 2023)","options":{"A":"5 માળી","B":"25 માળી","C":"10 માળી","D":"20 માળી"},"correct_answer":"A","explanation":"(M1 * H1) / W1 = (M2 * H2) / W2\n(5 * 5) / 25 = (M2 * 20) / 100\n25 / 25 = 20 * M2 / 100\n1 = M2 / 5 => M2 = 5 માળી.\nસાચો વિકલ્પ (A) છે."},{"question_number":24,"source":"સાંકળનો નિયમ .pdf","topic":"CCE 2023 PYQ - દિવાલ બનાવવી","question_text":"10 કામદારો 10 દિવસમાં દિવાલ બનાવી શકે છે. 5 દિવસમાં કામ પૂર્ણ કરવા માટે કેટલા વધારાના કામદારોની જરૂર પડશે? (CCE 2023)","options":{"A":"20 વધારાના કામદારો","B":"10 વધારાના કામદારો","C":"15 વધારાના કામદારો","D":"5 વધારાના કામદારો"},"correct_answer":"B","explanation":"M1 * D1 = M2 * D2\n10 * 10 = M2 * 5\n100 = 5 * M2 => M2 = 20 કામદારો.\nવધારાના કામદારો = 20 - 10 = 10 વધારાના કામદારો.\nસાચો વિકલ્પ (B) છે."},{"question_number":25,"source":"સાંકળનો નિયમ .pdf","topic":"CCE 2023 PYQ - કલાક અને દિવસો","question_text":"જો 15 માણસો દિવસમાં 4 કલાક કામ કરીને 18 દિવસમાં એક કામ કરી શકે છે. તો તે સમય શોધો કે જેમાં 27 માણસો દિવસમાં 2 કલાક કામ કરીને એ જ કામ કરી શકે છે. (CCE 2023)","options":{"A":"23 દિવસ","B":"20 દિવસ","C":"25 દિવસ","D":"15 દિવસ"},"correct_answer":"B","explanation":"M1 * D1 * H1 = M2 * D2 * H2\n15 * 18 * 4 = 27 * D2 * 2\n1080 = 54 * D2\nD2 = 1080 / 54 = 20 દિવસ.\nસાચો વિકલ્પ (B) છે."},{"question_number":26,"source":"સાંકળનો નિયમ .pdf","topic":"CCE 2023 PYQ - રંગકર્મી ટીમ","question_text":"4 રંગકર્મીઓની ટીમ 4 દિવસમાં 20 દિવાલોને પેઇન્ટ કરી શકે છે. 16 દિવસમાં 80 દિવાલોને રંગવા માટે કેટલા રંગકર્મીઓ જરૂરી છે? (CCE 2023)","options":{"A":"16 રંગકર્મીઓ","B":"8 રંગકર્મીઓ","C":"4 રંગકર્મીઓ","D":"20 રંગકર્મીઓ"},"correct_answer":"C","explanation":"(M1 * D1) / W1 = (M2 * D2) / W2\n(4 * 4) / 20 = (M2 * 16) / 80\n16 / 20 = 16 * M2 / 80\n4 / 5 = M2 / 5 => M2 = 4 રંગકર્મીઓ.\nસાચો વિકલ્પ (C) છે."},{"question_number":27,"source":"સાંકળનો નિયમ .pdf","topic":"CCE 2023 PYQ - કામનો ભાગ","question_text":"ગૌતમ એક કામ 47/2 દિવસમાં પૂર્ણ કરે છે. તે કામનો કયો ભાગ 4 દિવસમાં પૂર્ણ કરશે? (CCE 2023)","options":{"A":"8/47","B":"8/53","C":"47/8","D":"36/7"},"correct_answer":"A","explanation":"47/2 દિવસમાં કરેલું કામ = 1 ભાગ\n1 દિવસમાં કરેલું કામ = 2/47 ભાગ\nતેથી 4 દિવસમાં કરેલું કામ = 4 * (2/47) = 8/47 ભાગ.\nસાચો વિકલ્પ (A) છે."},{"question_number":28,"source":"સાંકળનો નિયમ .pdf","topic":"Type 2 - રાશન / હોસ્ટેલ ખાદ્યાન્ય (નવા વિદ્યાર્થીઓ)","question_text":"એક હોસ્ટેલમાં 100 વિદ્યાર્થીને 40 દિવસ ચાલે તેટલો અનાજ પુરવઠો છે. 4 દિવસ પછી 20 વિદ્યાર્થી નવા આવ્યા. હવે કેટલા દિવસ અનાજ પુરવઠો ચાલશે.","options":{"A":"24","B":"30","C":"32","D":"36"},"correct_answer":"B","explanation":"4 દિવસ પછી બાકી દિવસો = 40 - 4 = 36 દિવસ.\nનવા કુલ વિદ્યાર્થીઓ = 100 + 20 = 120.\nબાકી અનાજનો જથ્થો = 100 * 36.\nચાલશે તે દિવસો = (100 * 36) / 120 = 3600 / 120 = 30 દિવસ.\nસાચો વિકલ્પ (B) છે."},{"question_number":29,"source":"સાંકળનો નિયમ .pdf","topic":"Type 2 - અનાથાશ્રમ ખાદ્યાન્ય (વ્યક્તિઓ જતી રહી)","question_text":"એક અનાથાશ્રમમાં 275 વ્યક્તિઓ માટે 40 દિવસ ચાલે તેટલું ખાદ્યાન્ય છે જો 16 દિવસ પછી 125 વ્યક્તિઓ અનાથાશ્રમમાંથી જતી રહી તો હવે આ ખાદ્યાન્ય કેટલા દિવસ ચાલી શકે.","options":{"A":"33","B":"44","C":"55","D":"66"},"correct_answer":"B","explanation":"16 દિવસ પછી બાકી દિવસો = 40 - 16 = 24 દિવસ.\nબાકી બચેલી વ્યક્તિઓ = 275 - 125 = 150.\nચાલશે તે દિવસો = (275 * 24) / 150 = 6600 / 150 = 44 દિવસ.\nસાચો વિકલ્પ (B) છે."},{"question_number":30,"source":"સાંકળનો નિયમ .pdf","topic":"Type 2 - છાત્રાલય અનાજ (નવા દાખલ)","question_text":"એક છાત્રાલયના કોઠારમાં 280 વિદ્યાર્થીઓને 30 દિવસ ચાલે તેટલું અનાજ છે જો નવા 20 વિદ્યાર્થીઓ દાખલ થાય તો અનાજ કેટલા દિવસ ચાલે.","options":{"A":"25","B":"28","C":"21","D":"32"},"correct_answer":"B","explanation":"કુલ વિદ્યાર્થીઓ = 280 + 20 = 300.\nM1 * D1 = M2 * D2\n280 * 30 = 300 * D2\n8400 = 300 * D2 => D2 = 28 દિવસ.\nસાચો વિકલ્પ (B) છે."},{"question_number":31,"source":"સાંકળનો નિયમ .pdf","topic":"Type 2 - લશ્કરી છાવણી અનાજ","question_text":"એક લશ્કરી છાવણીમાં 1000 સૈનિકોને 30 દિવસ ચાલે તેટલો અનાજનો જથ્થો છે જો 10 દિવસ પછી 1000 બીજા સૈનિકો તે છાવણીમાં જોડાય તો બાકીનો અનાજનો જથ્થો કેટલા દિવસ ચાલશે.","options":{"A":"10","B":"15","C":"25","D":"20"},"correct_answer":"A","explanation":"10 દિવસ પછી બાકી દિવસો = 30 - 10 = 20 દિવસ.\nનવા કુલ સૈનિકો = 1000 + 1000 = 2000.\nબાકી અનાજ = 1000 * 20.\nચાલશે તે દિવસો = (1000 * 20) / 2000 = 10 દિવસ.\nસાચો વિકલ્પ (A) છે."},{"question_number":32,"source":"સાંકળનો નિયમ .pdf","topic":"Type 2 - કિલ્લામાં સૈનિકો ઉમેરાયા","question_text":"એક કિલ્લામાં 2100 સૈનિકો માટેનો 50 દિવસનો ખોરાક છે 10 દિવસ પછી થોડા વધુ સૈનિકો ઉમેરાતા તે ખોરાક 25 દિવસ ચાલે છે તો કેટલા સૈનિકો ઉમેરાયા હશે.","options":{"A":"3360","B":"2160","C":"1260","D":"2100"},"correct_answer":"C","explanation":"10 દિવસ પછી બાકી દિવસો = 50 - 10 = 40 દિવસ.\nકુલ ખોરાક જથ્થો = 2100 * 40 = 84000.\nનવી સૈનિકોની સંખ્યા = 84000 / 25 = 3360.\nઉમેરાયેલા સૈનિકો = 3360 - 2100 = 1260 સૈનિકો.\nસાચો વિકલ્પ (C) છે."},{"question_number":33,"source":"સાંકળનો નિયમ .pdf","topic":"Type 2 - કિલ્લામાં પ્રારંભિક સૈનિકો શોધવા","question_text":"એક કિલ્લામાં 35 દિવસ ચાલે તેટલું અનાજ ઉપલબ્ધ છે જો 5 દિવસ પછી 450 વધુ વ્યક્તિઓ કિલ્લામાં આવે તો અનાજ 20 દિવસ ચાલે છે તો કિલ્લામાં શરૂઆતમાં કેટલાક વ્યક્તિઓ હશે.","options":{"A":"600","B":"700","C":"800","D":"900"},"correct_answer":"D","explanation":"ધારો કે પ્રારંભમાં x વ્યક્તિઓ હતી.\n5 દિવસ પછી બાકી દિવસો = 35 - 5 = 30 દિવસ.\nx * 30 = (x + 450) * 20\n30x = 20x + 9000\n10x = 9000 => x = 900 વ્યક્તિઓ.\nસાચો વિકલ્પ (D) છે."},{"question_number":34,"source":"સાંકળનો નિયમ .pdf","topic":"CCE 2023 PYQ - પ્રારંભિક સૈનિકો છોડી ગયા","question_text":"સૈનિકોના એક કેમ્પમાં 100 દિવસનું ભોજન હોય છે. 10 દિવસ બાદ, 40 સૈનિકો કેમ્પ છોડીને જાય છે. પરિણામે, ત્યારથી ખોરાક 120 દિવસ સુધી ચાલી શકે છે. તો સૈનિકોની પ્રારંભિક સંખ્યા કેટલી હતી? (CCE 2023)","options":{"A":"140","B":"160","C":"130","D":"180"},"correct_answer":"B","explanation":"ધારો કે પ્રારંભિક સૈનિકો x હતા.\n10 દિવસ પછી બાકી દિવસો = 100 - 10 = 90 દિવસ.\nx * 90 = (x - 40) * 120\n90x = 120x - 4800\n30x = 4800 => x = 160 સૈનિકો.\nસાચો વિકલ્પ (B) છે."}]},"work":{"subject":"Mathematics / Quantitative Aptitude","chapter_title":"સમય, કાર્ય અને વેતન (Time, Work & Wages - Lecture 1 & Lecture 2)","sources_included":["સમય, કાર્ય અને વેતન Lecture 1.pdf","સમય, કાર્ય અને વેતન Lecture 2.pdf"],"total_questions_count":46,"concept_notes":[{"topic":"મૂળભૂત વ્યાખ્યા અને સૂત્રો (Efficiency & Work Formulas)","details":"૧. કાર્યક્ષમતા (Efficiency) = એકમ સમયમાં કરેલું કાર્ય = કાર્ય / સમય.\n૨. સમય (Time) = કુલ કાર્ય / કાર્યક્ષમતા.\n૩. કુલ કાર્ય (Total Work) = સમય × કાર્યક્ષમતા.\n૪. કાર્યક્ષમતા અને સમય વચ્ચે વ્યસ્ત સંબંધ હોય છે (Efficiency ∝ 1 / Time)."},{"topic":"લસાઅ પદ્ધતિ (LCM Method for Time & Work)","details":"૧. આપેલા સમય (દિવસો/કલાકો) નો લસાઅ શોધી તેને 'કુલ કાર્ય' (Total Work Units) ધારો.\n૨. કુલ કાર્યને વ્યક્તિના સમય વડે ભાગી દરેકની દૈનિક/કલાકડી કાર્યક્ષમતા (One Day/Hour Work) શોધો.\n૩. સાથે મળીને કામ કરતી વખતે તેમની કાર્યક્ષમતાઓનો સરવાળો કરી કુલ કાર્ય વડે ભાગો."},{"topic":"કામ છોડી જવું અથવા નવું જોડાવું (Leaving & Joining Rules)","details":"૧. કામ પૂરું થયા પછી છોડી જવું: જે તે વ્યક્તિએ કરેલું કામ બાદ કરી બાકીનું કામ બીજા પાસે કરાવો.\n૨. કામ પૂરું થવાના થોડા દિવસ પહેલાં છોડી જવું: છોડી જનાર વ્યક્તિના દિવસોનું કામ કુલ કામમાં ઉમેરી (Add back method) બધાની ભેગી કાર્યક્ષમતા વડે ભાગો."},{"topic":"વૈકલ્પિક દિવસો / એકાંતરે કામ (Alternate Days Work)","details":"૧. પ્રથમ દિવસે A અને બીજા દિવસે B કામ કરે તો ૨ દિવસનું કુલ કામ શોધો.\n૨. કુલ કામની નજીક પહોંચવા માટે ચક્ર (Cycles) ગુણો અને બાકી વધેલું કામ આગામી વ્યક્તિ પાસે કરાવો."},{"topic":"વેતન અને મહેનતાણું (Work & Wages)","details":"૧. જો બધા વ્યક્તિઓ સરખા સમય માટે કામ કરે, તો વેતનની વહેંચણી તેમની કાર્યક્ષમતાના ગુણોત્તરમાં થાય છે.\n૨. જો અલગ-અલગ સમય માટે કામ કરે, તો વેતનની વહેંચણી તેમણે કરેલા 'કુલ કામના ભાગ' ના ગુણોત્તરમાં થાય છે."},{"topic":"સાંકળનો નિયમ (Chain Rule / MDH Formula)","details":"૧. સૂત્ર: (M1 × D1 × H1) / W1 = (M2 × D2 × H2) / W2.\n૨. M = માણસોની સંખ્યા, D = દિવસો, H = દૈનિક કલાકો, W = કરેલું કાર્ય/મજૂરી."}],"questions":[{"question_number":1,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"કામનો દર (Work Rate)","question_text":"લીલા એક કામ 15 મિનિટમાં પૂર્ણ કરે છે તો તેનો કામનો દર પ્રતિ સેકન્ડ માં શોધો.","options":{"A":"1/15","B":"1/600","C":"1/900","D":"1/300"},"correct_answer":"C","explanation":"૧૫ મિનિટ = ૧૫ × ૬૦ સેકન્ડ = ૯૦૦ સેકન્ડ. તેથી પ્રતિ સેકન્ડ કામનો દર = ૧ / ૯૦૦."},{"question_number":2,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"કામનો દર (Work Rate)","question_text":"યંત્ર A, 2 કલાકમાં 1/5 ભાગનું કામ કરે છે તો તેનો કામનો દર પ્રતિમિનિટ માં શોધો.","options":{"A":"1/12","B":"1/10","C":"1/60","D":"1/600"},"correct_answer":"D","explanation":"૨ કલાક = ૧૨૦ મિનિટ. ૧૨૦ મિનિટમાં ૧/૫ ભાગનું કામ, તેથી ૧ મિનિટમાં કામનો દર = (૧/૫) / ૧૨૦ = ૧ / ૬૦૦."},{"question_number":3,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"અપૂર્ણાંક કાર્ય (Fractional Work - CCE 2023)","question_text":"જો આકાશ એકલો એક કામનો 4/5 ભાગ 20 દિવસમાં પૂરો કરી શકતો હોય, તો આકાશ તે જ કામનો 1/4 ભાગ કેટલા દિવસોમાં પૂરો કરી શકે?","options":{"A":"7 દિવસ","B":"6.25 દિવસ","C":"9 દિવસ","D":"8 દિવસ"},"correct_answer":"B","explanation":"૪/૫ ભાગ = ૨૦ દિવસ ⇒ પૂરૂં કામ = ૨૦ × ૫ / ૪ = ૨૫ દિવસ. તેથી ૧/૪ ભાગ કરવા માટેનો સમય = ૨૫ / ૪ = ૬.૨૫ દિવસ."},{"question_number":4,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"પેજ ટાઇપિંગ અને સંયુક્ત દર (CCE 2023)","question_text":"કૌશલ અને કમલ એક અસાઇનમેન્ટ પર કામ કરી રહ્યા છે. કૌશલને કમ્પ્યુટર પર 56 પેજ ટાઇપ કરવામાં 8 કલાક લાગે છે, જ્યારે કે કમલને 54 પેજ ટાઇપ કરવામાં 6 કલાક લાગે છે. તો 144 પેજની એક અસાઇનમેન્ટ ટાઇપ કરવા બે અલગ-અલગ કમ્પ્યુટર્સ પર સાથે કામ શરૂ કરતા તેઓ કેટલો સમય લેશે?","options":{"A":"10 કલાક","B":"9 કલાક","C":"8 કલાક","D":"6 કલાક"},"correct_answer":"B","explanation":"કૌશલનો દર = ૫૬ / ૮ = ૭ પેજ/કલાક. કમલનો દર = ૫૪ / ૬ = ૯ પેજ/કલાક. બંનેનો ભેગો દર = ૭ + ૯ = ૧૬ પેજ/કલાક. ૧૪૪ પેજ ટાઇપ કરવાનો સમય = ૧૪૪ / ૧૬ = ૯ કલાક."},{"question_number":5,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"પેજ ટાઇપિંગ સંયુક્ત દર (CCE 2023)","question_text":"રમેશ અને તુષાર એક અસાઇનમેન્ટ પર કામ કરી રહ્યા છે. રમેશને કમ્પ્યુટર પર 45 પેજ ટાઇપ કરવામાં 9 કલાક લાગે છે, જ્યારે તુષારને 40 પેજ ટાઇપ કરવામાં 5 કલાક લાગે છે. 78 પેજની અસાઇનમેન્ટ ટાઇપ કરવા માટે બે જુદા-જુદા કમ્પ્યુટર પર સાથે મળીને કામ કરતાં તેઓ કેટલો સમય લેશે?","options":{"A":"3 કલાક","B":"5 કલાક","C":"8 કલાક","D":"6 કલાક"},"correct_answer":"D","explanation":"રમેશનો દર = ૪૫ / ૯ = ૫ પેજ/કલાક. તુષારનો દર = ૪૦ / ૫ = ૮ પેજ/કલાક. ભેગો દર = ૫ + ૮ = ૧૩ પેજ/કલાક. ૭૮ પેજ માટે સમય = ૭૮ / ૧૩ = ૬ કલાક."},{"question_number":6,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"તબક્કાવાર પેજ ટાઇપિંગ (CCE 2023)","question_text":"R અને Sને સાથે મળીને 500 પાના ધરાવતું એક પુસ્તક ટાઇપ કરવાનું છે. એકલા Rને 160 પેજ ટાઇપ કરવામાં 20 કલાક લાગે છે અને એકલા Sને 100 પેજ ટાઇપ કરવામાં 25 કલાક લાગે છે. એકલા Rએ પ્રથમ 200 પેજ ટાઇપ કર્યા અને છેલ્લા 300 પેજ R અને S દ્વારા સાથે મળીને ટાઇપ કરવામાં આવ્યા. તો સંપૂર્ણ પુસ્તક ટાઇપ કરવામાં કેટલો સમય લાગશે?","options":{"A":"75 કલાક","B":"65 કલાક","C":"70 કલાક","D":"50 કલાક"},"correct_answer":"D","explanation":"R નો દર = ૧૬૦ / ૨૦ = ૮ પેજ/કલાક. S નો દર = ૧૦૦ / ૨૫ = ૪ પેજ/કલાક. પ્રથમ ૨૦૦ પેજ R એકલો કરે છે: ૨૦૦ / ૮ = ૨૫ કલાક. બાકીના ૩૦૦ પેજ બંને ભેગા (૮ + ૪ = ૧૨ પેજ/કલાક) કરે છે: ૩૦૦ / ૧૨ = ૨૫ કલાક. કુલ સમય = ૨૫ + ૨૫ = ૫૦ કલાક."},{"question_number":7,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"તબક્કાવાર પેજ ટાઇપિંગ [HW] (CCE 2023)","question_text":"R અને Sને સાથે મળીને 400 પાના ધરાવતું એક પુસ્તક ટાઇપ કરવાનું છે. R ને 128 પાના ટાઇપ કરવામાં 16 કલાક લાગે છે અને S ને 80 પાના ટાઇપ કરવામાં 20 કલાક લાગે છે. R એ એકલાએ પ્રથમ 160 પાના ટાઇપ કર્યા અને છેલ્લા 240 પાના R અને S એ સાથે મળીને ટાઇપ કર્યા. સંપૂર્ણ પુસ્તક ટાઇપ કરવામાં કેટલો સમય લાગશે?","options":{"A":"40 કલાક","B":"45 કલાક","C":"65 કલાક","D":"55 કલાક"},"correct_answer":"A","explanation":"R નો દર = ૧૨૮ / ૧૬ = ૮ પેજ/કલાક. S નો દર = ૮૦ / ૨૦ = ૪ પેજ/કલાક. પ્રથમ ૧૬૦ પેજ માટે R નો સમય = ૧૬૦ / ૮ = ૨૦ કલાક. બાકીના ૨૪૦ પેજ માટે R+S નો દર = ૮+૪=૧૨, સમય = ૨૪૦ / ૧૨ = ૨૦ કલાક. કુલ સમય = ૨૦ + ૨૦ = ૪૦ કલાક."},{"question_number":8,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"સંયુક્ત કાર્ય - ૨ વ્યક્તિઓ (Simple LCM)","question_text":"રમેશ કોઈ કાર્ય 20 દિવસમાં અને સુરેશ તે જ કાર્ય 30 દિવસ પૂર્ણ કરે છે. જો બંને એક સાથે કાર્ય કરવાનું શરૂ કરે તો તે કાર્ય કેટલા દિવસ માં પૂર્ણ થશે?","options":{"A":"10","B":"12","C":"15","D":"8"},"correct_answer":"B","explanation":"૨૦ અને ૩૦ નો લસાઅ = ૬૦ (કુલ કાર્ય). રમેશની ક્ષમતા = ૩, સુરેશની ક્ષમતા = ૨. કુલ ક્ષમતા = ૫. સમય = ૬૦ / ૫ = ૧૨ દિવસ."},{"question_number":9,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"સંયુક્ત કાર્ય - ૨ વ્યક્તિઓ (LCM)","question_text":"રમેશ કોઈ કાર્ય 8 દિવસમાં અને સુરેશ તે જ કાર્ય 5 દિવસ પૂર્ણ કરે છે. જો બંને એક સાથે કાર્ય કરવાનું શરૂ કરે તો તે કાર્ય કેટલા દિવસ માં પૂર્ણ થશે?","options":{"A":"2 1/13","B":"2 2/13","C":"3 1/13","D":"3 3/13"},"correct_answer":"C","explanation":"૮ અને ૫ નો લસાઅ = ૪૦. રમેશ = ૫, સુરેશ = ૮. કુલ ક્ષમતા = ૧૩. સમય = ૪૦ / ૧૩ = ૩ (૧/૧૩) દિવસ."},{"question_number":10,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"ટાયર પંચર લીકેજ દર (CCE 2023)","question_text":"એક ટાયરમાં બે પંકચર હોય છે. એકલા પ્રથમ પંકચરથી 15 મિનિટમાં ટાયર ફ્લેટ (સમતલ) થઈ જશે અને એકલા બીજા પંચરથી 9 મિનિટમાં તે ફ્લેટ થઈ જશે. જો હવા સ્થિર દરે બહાર નીકળે છે, તો તેને ફ્લેટ (સમતલ) બનાવવામાં બંને પંચરને એકસાથે કેટલો સમય લાગે છે?","options":{"A":"6.625 મિનિટ","B":"7.625 મિનિટ","C":"5.625 મિનિટ","D":"4.625 મિનિટ"},"correct_answer":"C","explanation":"સમય = (૧૫ × ૯) / (૧૫ + ૯) = ૧૩૫ / ૨૪ = ૫.૬૨૫ મિનિટ."},{"question_number":11,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"ટાયર પંચર લીકેજ દર (CCE 2023)","question_text":"એક ટાયરમાં બે પંચર છે. એકલા પ્રથમ પંચરે 34 મિનિટમાં ટાયરને ફ્લેટ(સપાટ) બનાવ્યું હોત અને બીજા પંચરે એકલાએ તેને 5 મિનિટમાં કર્યું હોત. જો હવા સ્થિર દરે બહાર નીકળે છે, તો બંને પંચરને એકસાથે તેને ફ્લેટ(સપાટ) બનાવવામાં કેટલો સમય લાગે?","options":{"A":"5 મિનિટ","B":"3.30 મિનિટ","C":"3.68 મિનિટ","D":"4.66 મિનિટ"},"correct_answer":"D","explanation":"સમય = (૩૪ × ૫) / (૩૪ + ૫) = ૧૭૦ / ૩૯ ≈ ૪.૬૬ મિનિટ."},{"question_number":12,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"સંયુક્ત કાર્ય - ૩ વ્યક્તિઓ (CCE 2023)","question_text":"ત્રણ કામદારો, X, Y, અને Z એક પ્રોજેક્ટ માટે ટીમ બનાવે છે. X એકલો પ્રોજેક્ટને 12 દિવસમાં, Y એકલો 18 દિવસમાં અને Z એકલો 24 દિવસમાં પૂર્ણ કરી શકે છે. જો તેઓ સાથે મળીને પ્રોજેક્ટ કરવાનું નક્કી કરે છે, તો પ્રોજેક્ટને પૂર્ણ કરવામાં કેટલો સમય લાગશે?","options":{"A":"6.5 દિવસ","B":"5.5 દિવસ","C":"7.5 દિવસ","D":"8.5 દિવસ"},"correct_answer":"B","explanation":"૧૨, ૧૮ અને ૨૪ નો લસાઅ = ૭૨ (કુલ કાર્ય). X = ૬, Y = ૪, Z = ૩. કુલ ક્ષમતા = ૧૩. સમય = ૭૨ / ૧૩ ≈ ૫.૫ દિવસ."},{"question_number":13,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"દૈનિક કલાકો સાથે સમય અને કાર્ય (CCE 2023)","question_text":"દરરોજ 3 કલાક કામ કરવાથી, R1 એકલો 16 દિવસમાં કામ પૂર્ણ કરી શકે છે. દરરોજ 8 કલાક કામ કરવાથી, R2 એકલા એ જ કામ 6 દિવસમાં પૂર્ણ કરી શકે છે. દરરોજ 12 કલાક કામ કરવાથી, R1 અને R2 બંને એકસાથે કેટલા દિવસમાં એ જ કાર્ય પૂર્ણ કરી શકે છે?","options":{"A":"3 દિવસ","B":"4 દિવસ","C":"2 દિવસ","D":"5 દિવસ"},"correct_answer":"C","explanation":"R1 ના કુલ કલાક = ૩ × ૧૬ = ૪૮ કલાક. R2 ના કુલ કલાક = ૮ × ૬ = ૪૮ કલાક. બંને ભેગા મળીને કુલ કલાક = ૪૮ / ૨ = ૨૪ કલાક. જો દરરોજ ૧૨ કલાક કામ કરે તો દિવસો = ૨૪ / ૧૨ = ૨ દિવસ."},{"question_number":14,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"દૈનિક કલાકો સાથે સમય અને કાર્ય [HW] (CCE 2023)","question_text":"દરરોજ 9 કલાક કામ કરીને, R1 એકલા જ 12 દિવસમાં કામ પુરૂ કરી શકે છે. દરરોજ 3 કલાક કામ કરીને, R2 એકલા જ એ જ કામને 18 દિવસમાં પૂર્ણ કરી શકે છે. રોજના 9 કલાક કામ કરવાથી, R1 અને R2 બંને સાથે મળીને કેટલા દિવસમાં એ જ કામ પુરૂ કરી શકે છે?","options":{"A":"8 દિવસ","B":"5 દિવસ","C":"9 દિવસ","D":"4 દિવસ"},"correct_answer":"D","explanation":"R1 ના કુલ કલાક = ૯ × ૧૨ = ૧૦૮. R2 ના કુલ કલાક = ૩ × ૧૮ = ૫૪. ૧૦૮ અને ૫૪ નો લસાઅ = ૧૦૮. R1 = ૧, R2 = ૨. કુલ ક્ષમતા = ૩. કલાક = ૧૦૮ / ૩ = ૩૬ કલાક. જો દરરોજ ૯ કલાક કામ કરે તો દિવસો = ૩૬ / ૯ = ૪ દિવસ."},{"question_number":15,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"એકલા વ્યક્તિનું કાર્ય શોધવું (CCE 2023)","question_text":"M અને N સાથે મળીને 24 દિવસમાં એક કાર્ય પૂર્ણ કરી શકે છે. N એકલો એ જ કામ 72 દિવસમાં પૂર્ણ કરી શકે છે. M એકલો એ જ કામ કેટલા દિવસમાં પૂરું કરશે?","options":{"A":"42 દિવસ","B":"56 દિવસ","C":"46 દિવસ","D":"36 દિવસ"},"correct_answer":"D","explanation":"M+N = ૨૪, N = ૭૨. લસાઅ = ૭૨. M+N ની ક્ષમતા = ૩, N ની ક્ષમતા = ૧. M ની ક્ષમતા = ૩ - ૧ = ૨. M નો સમય = ૭૨ / ૨ = ૩૬ દિવસ."},{"question_number":16,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"એકલા વ્યક્તિનું કાર્ય શોધવું (CCE 2023)","question_text":"વિકાસ અને મોહન એક કામને પૂરું કરવા માટે 8 દિવસ કામ કરે છે. જો વિકાસ એકલો એ કામને 10 દિવસમાં પૂરું કરે તો, મોહન એકલો એ કામને પૂરું કરવામાં કેટલા દિવસ લેશે?","options":{"A":"16 દિવસ","B":"20 દિવસ","C":"40 દિવસ","D":"35 દિવસ"},"correct_answer":"C","explanation":"V+M = ૮, V = ૧૦. લસાઅ = ૪૦. V+M ક્ષમતા = ૫, V ક્ષમતા = ૪. M ક્ષમતા = ૧. M નો સમય = ૪૦ / ૧ = ૪૦ દિવસ."},{"question_number":17,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"દિવાલ તોડવાનું કામ (CCE 2023)","question_text":"A અને B મળીને 30 દિવસમાં દિવાલ તોડી શકે છે. જો A એકલો તેને 45 દિવસમાં તોડી શકે છે, તો તે સમય શોધો કે જેમાં B એકલો તેને તોડી શકે.","options":{"A":"45 દિવસ","B":"60 દિવસ","C":"90 દિવસ","D":"30 દિવસ"},"correct_answer":"C","explanation":"B નો સમય = (૪૫ × ૩૦) / (૪૫ - ૩૦) = ૧૩૫૦ / ૧૫ = ૯૦ દિવસ."},{"question_number":18,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"એકલા વ્યક્તિનું કાર્ય (CCE 2023)","question_text":"રમેશ, સુરેશ અને કરણ સાથે મળીને 30 મિનિટમાં એક ખુરશી બનાવી શકે છે. રમેશ અને સુરેશ મળીને તે 50 મિનિટમાં બનાવી શકે છે. એકલા કરણને તે ખુરશી બનાવવામાં કેટલો સમય લાગશે?","options":{"A":"100 મિનિટ","B":"85 મિનિટ","C":"75 મિનિટ","D":"90 મિનિટ"},"correct_answer":"C","explanation":"કરણનો સમય = (૫૦ × ૩૦) / (૫૦ - ૩૦) = ૧૫૦૦ / ૨૦ = ૭૫ મિનિટ."},{"question_number":19,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"જોડીમાં કાર્ય (Pair Work - CCE 2023)","question_text":"P અને Q 18 દિવસમાં એક કામ કરી શકે છે. Q અને R એ જ કામ 10 દિવસમાં કરી શકે છે, જ્યારે R અને P તેને 15 દિવસમાં કરી શકે છે. જ્યારે P, Q અને R એકસાથે કામ કરે છે ત્યારે કામ કેટલા દિવસમાં પૂરું થશે?","options":{"A":"8 દિવસ","B":"6 દિવસ","C":"9 દિવસ","D":"11 દિવસ"},"correct_answer":"C","explanation":"૧૮, ૧૦ અને ૧૫ નો લસાઅ = ૯૦ (કુલ કાર્ય). P+Q = ૫, Q+R = ૯, R+P = ૬. ૨(P+Q+R) = ૨૦ ⇒ P+Q+R ની ક્ષમતા = ૧૦. P,Q,R નો સમય = ૯૦ / ૧૦ = ૯ દિવસ."},{"question_number":20,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"અન્ય વ્યક્તિ C ની મદદથી કાર્ય (CCE 2023)","question_text":"A બે આપેલા સ્ટેશનો વચ્ચે રેલ્વે ટ્રેક 15 દિવસમાં બિછાવી શકે છે. અને B તે જ કામ 12 દિવસમાં કરી શકે છે. C ની મદદથી, તેમણે માત્ર 5 દિવસમાં જ કામ કર્યું. તો પછી C એકલા ____ માં કામ કરી શકે છે.","options":{"A":"25 દિવસ","B":"20 દિવસ","C":"18 દિવસ","D":"32 દિવસ"},"correct_answer":"B","explanation":"૧૫, ૧૨ અને ૫ નો લસાઅ = ૬૦. A = ૪, B = ૫, A+B+C = ૧૨. C ની ક્ષમતા = ૧૨ - (૪ + ૫) = ૩. C નો સમય = ૬૦ / ૩ = ૨૦ દિવસ."},{"question_number":21,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"અંતર અને તફાવત આધારિત સમય અને કાર્ય (CCE 2023)","question_text":"A1, A2 અને A3 મળીને A1 કરતાં 210 દિવસ ઓછા સમયમાં, A2 કરતાં 105 દિવસ ઓછા સમયમાં એક કાર્ય પૂર્ણ કરી શકે છે. A1, A2 અને A3 સાથે મળીને એ જ કાર્યને પૂર્ણ કરવામાં 105 દિવસ લે છે. તો A1 અને A2 સાથે મળીને કેટલા દિવસમાં એ જ કાર્ય પૂર્ણ કરી શકશે?","options":{"A":"126 દિવસ","B":"176 દિવસ","C":"156 દિવસ","D":"150 દિવસ"},"correct_answer":"A","explanation":"A1+A2+A3 = ૧૦૫ દિવસ. A1 = ૧૦૫ + ૨૧૦ = ૩૧૫ દિવસ, A2 = ૧૦૫ + ૧૦૫ = ૨૧૦ દિવસ. ૩૧૫ અને ૨૧૦ નો લસાઅ = ૬૩૦. A1 ની ક્ષમતા = ૨, A2 ની ક્ષમતા = ૩. A1+A2 નો ભેગો સમય = ૬૩૦ / ૫ = ૧૨૬ દિવસ."},{"question_number":22,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"વૈકલ્પિક દિવસો / Alternate Days (CCE 2023)","question_text":"A અને B અલગ-અલગ કામ કરતા એક કામ અનુક્રમે 8 અને 10 દિવસમાં પૂરું કરી શકે છે. જો તેઓ એકાંતરે એક દિવસ કામ કરે, તો કેટલા દિવસમાં કામ પૂર્ણ થશે?","options":{"A":"9 દિવસ","B":"12.3 દિવસ","C":"10.4 દિવસ","D":"8.8 દિવસ"},"correct_answer":"D","explanation":"૮ અને ૧૦ નો લસાઅ = ૪૦. A ની ક્ષમતા = ૫, B ની ક્ષમતા = ૪. ૨ દિવસનું કામ = ૯. ૪ ચક્ર (૮ દિવસ) માં કામ = ૩૬. બાકી કામ = ૪ (જે A કરશે). સમય = ૪/૫ = ૦.૮ દિવસ. કુલ સમય = ૮.૮ દિવસ."},{"question_number":23,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"વૈકલ્પિક કલાકો (CCE 2023)","question_text":"અમન એક મશીન 8 કલાકમાં જોડી શકે છે. ભાર્ગવ એ જ મશીનને 12 કલાકમાં જોડી શકે છે. અમન જોડાણ કરવાનું શરૂ કરે છે અને તેઓ એક કલાક પછી વૈકલ્પિક રીતે કામ કરવાનું નક્કી કરે છે. મશીનનું જોડાણ કેટલા કલાકમાં પૂર્ણ થશે?","options":{"A":"10 કલાક","B":"9 કલાક","C":"8.5 કલાક","D":"9.5 કલાક"},"correct_answer":"D","explanation":"૮ અને ૧૨ નો લસાઅ = ૨૪. અમન = ૩, ભાર્ગવ = ૨. ૨ કલાકમાં ૫ એકમ કામ. ૪ ચક્ર (૮ કલાક) માં ૨૦ એકમ કામ. ૯માં કલાકે અમન ૩ એકમ કરશે (કુલ ૨૩ એકમ). બાકી ૧ એકમ ભાર્ગવ ૧/૨ કલાકમાં કરશે. કુલ સમય = ૯.૫ કલાક."},{"question_number":24,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"દર ત્રીજા દિવસે મદદ (CCE 2023)","question_text":"એક બિલ્ડર તેની એક સાઇટ પર ત્રણ બાંધકામ કામદારો રમેશ, રાજુ અને રાકેશની નિમણૂક કરે છે. તેઓ એક કામ કરવા માટે અનુક્રમે 20, 30 અને 60 દિવસ લે છે. જો રમેશને દર ત્રીજા દિવસે રાજુ અને રાકેશ મદદ કરે તો રમેશને આખું કામ પૂરું કરવામાં કેટલા દિવસો લાગશે?","options":{"A":"30 દિવસ","B":"25 દિવસ","C":"40 દિવસ","D":"15 દિવસ"},"correct_answer":"D","explanation":"૨૦, ૩૦, ૬૦ નો લસાઅ = ૬૦. રમેશ = ૩, રાજુ = ૨, રાકેશ = ૧. પ્રથમ ૨ દિવસ રમેશ કામ કરે = ૩ + ૩ = ૬. ૩જા દિવસે ત્રણેય કરે = ૩ + ૨ + ૧ = ૬. ૩ દિવસમાં કુલ કામ = ૧૨. ૬૦ એકમ કામ કરવા માટે સમય = (૬૦/૧૨) × ૩ = ૧૫ દિવસ."},{"question_number":25,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"બાકી રહેતું કાર્ય (Remaining Work - CCE 2023)","question_text":"A એક કામ 15 દિવસમાં અને B તેને 20 દિવસમાં કરી શકે છે. જો તેઓ તેના પર 3 દિવસ સાથે મળીને કામ કરે છે, તો કેટલા ભાગનું કામ બાકી છે?","options":{"A":"13/20","B":"7/20","C":"13/10","D":"7/10"},"correct_answer":"A","explanation":"૧૫ અને ૨૦ નો લસાઅ = ૬૦. A = ૪, B = ૩. ૩ દિવસનું કામ = ૩ × (૪ + ૩) = ૨૧. બાકી કામ = ૬૦ - ૨૧ = ૩૯. બાકી ભાગ = ૩૯ / ૬૦ = ૧૩ / ૨૦."},{"question_number":26,"source":"સમય, કાર્ય અને વેતન Lecture 1.pdf","topic":"વિધાનોની ચકાસણી (Statement Verification - CCE 2023)","question_text":"A એક કામનો 3/10 ભાગ 18 દિવસમાં પૂર્ણ કરી શકે છે. B એ જ કામનો 7/10 ભાગ 17.5 દિવસમાં પૂર્ણ કરી શકે છે. નીચેનામાંથી કયું વિધાન સાચું/સાચા છે? I. A એ B કરતાં વધુ કાર્યક્ષમ છે. II. A અને B એકસાથે કામ કરીને 15 દિવસમાં એ જ કામનો 17/20 ભાગ પૂર્ણ કરી શકે છે.","options":{"A":"ન તો I કે ન તો II","B":"માત્ર I","C":"માત્ર II","D":"I અને II બંને"},"correct_answer":"C","explanation":"A નું પૂરૂં કામ = ૧૮ × ૧૦ / ૩ = ૬૦ દિવસ. B નું પૂરૂં કામ = ૧૭.૫ × ૧૦ / ૭ = ૨૫ દિવસ. B ઝડપી છે માટે I ખોટું છે. ૬૦ અને ૨૫ નો લસાઅ = ૩૦૦. A = ૫, B = ૧૨. ૧૫ દિવસમાં કામ = ૧૫ × ૧૭ = ૨૫૫. ભાગ = ૨૫૫ / ૩૦૦ = ૧૭ / ૨૦. માટે II સાચું છે."},{"question_number":27,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"વચ્ચેથી કામ છોડી જવું (Leaving Work Halfway - CCE 2023)","question_text":"R એકલો 12.5 દિવસમાં એક ટેબલ બનાવી શકે છે જ્યારે S એકલો 25 દિવસમાં તેને બનાવી શકે છે. S એ કામ શરૂ કર્યું અને 5 દિવસ કામ કર્યું. તો R કેટલા દિવસમાં બાકીનું કામ પૂરું કરી શકશે?","options":{"A":"12 દિવસ","B":"15 દિવસ","C":"12.5 દિવસ","D":"10 દિવસ"},"correct_answer":"D","explanation":"૧૨.૫ અને ૨૫ નો લસાઅ = ૨૫. R ની ક્ષમતા = ૨, S ની ક્ષમતા = ૧. S નું ૫ દિવસનું કામ = ૫ × ૧ = ૫. બાકી કામ = ૨૫ - ૫ = ૨૦. R નો સમય = ૨૦ / ૨ = ૧૦ દિવસ."},{"question_number":28,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"વચ્ચેથી કામ છોડી જવું (CCE 2023)","question_text":"E એકલો 25 દિવસમાં એક ટેબલ બનાવી શકે છે જ્યારે F એકલો તેને 50 દિવસમાં બનાવી શકે છે. F એ કામ શરૂ કર્યું અને 10 દિવસ કામ કર્યું. E કેટલા દિવસમાં બાકીનું કામ પૂરું કરી શકશે?","options":{"A":"28 દિવસ","B":"24 દિવસ","C":"20 દિવસ","D":"25 દિવસ"},"correct_answer":"C","explanation":"૨૫ અને ૫૦ નો લસાઅ = ૫૦. E = ૨, F = ૧. F નું ૧૦ દિવસનું કામ = ૧૦. બાકી કામ = ૪૦. E નો સમય = ૪૦ / ૨ = ૨૦ દિવસ."},{"question_number":29,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"સાથે કામ કર્યા પછી છોડી જવું (CCE 2023)","question_text":"સતીશ 15 દિવસમાં એક કામ પૂરું કરી શકે છે અને મહેશ એ જ કામ 20 દિવસમાં પૂરું કરી શકે છે. તેઓ 4 દિવસ સાથે કામ કરે છે, ત્યારબાદ સતીશ જતો રહે છે અને મહેશ કામ કરવાનું ચાલુ રાખે છે. મહેશને કામ પૂરું કરવા વધુ કેટલા દિવસો લાગશે?","options":{"A":"13.33 દિવસ","B":"14.67 દિવસ","C":"10.67 દિવસ","D":"11.67 દિવસ"},"correct_answer":"C","explanation":"૧૫ અને ૨૦ નો લસાઅ = ૬૦. સતીશ = ૪, મહેશ = ૩. ૪ દિવસનું ભેગું કામ = ૪ × (૪ + ૩) = ૨૮. બાકી કામ = ૬૦ - ૨૮ = ૩૨. મહેશનો બાકી સમય = ૩૨ / ૩ = ૧૦.૬૭ દિવસ."},{"question_number":30,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"કલાક આધારિત કામ છોડી જવું (CCE 2023)","question_text":"મોહન અને રામ અનુક્રમે 8 કલાક અને 10 કલાકમાં એક દીવાલને પેઇન્ટ કરી શકે છે. બંને સાથે મળીને કામ શરૂ કરે છે, પરંતુ મોહન 2 કલાક પછી જતો રહે છે. બાકીનો ભાગ પૂરો કરવા માટે રામે લીધેલો સમય શોધો.","options":{"A":"5 કલાક 30 મિનિટ","B":"8 કલાક","C":"7 કલાક 30 મિનિટ","D":"6 કલાક"},"correct_answer":"A","explanation":"૮ અને ૧૦ નો લસાઅ = ૪૦. મોહન = ૫, રામ = ૪. ૨ કલાકનું ભેગું કામ = ૨ × ૯ = ૧૮. બાકી કામ = ૪૦ - ૧૮ = ૨૨. રામનો સમય = ૨૨ / ૪ = ૫.૫ કલાક = ૫ કલાક ૩૦ મિનિટ."},{"question_number":31,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"કેટલા દિવસ પછી કામ છોડ્યું તે શોધો (CCE 2023)","question_text":"અમન અને ચંદન અનુક્રમે 45 અને 40 દિવસમાં એક કામ કરી શકે છે. તેઓ સાથે કામ કરવા લાગ્યા પરંતુ અમને થોડા દિવસો પછી કામ છોડી દીધું. ચંદને બાકીનું કામ 23 દિવસમાં કર્યું. તો અમન કેટલા દિવસ પછી કામ છોડીને ગયો?","options":{"A":"8 દિવસ","B":"6 દિવસ","C":"10 દિવસ","D":"9 દિવસ"},"correct_answer":"D","explanation":"૪૫ અને ૪૦ નો લસાઅ = ૩૬૦. અમન = ૮, ચંદન = ૯. ચંદનનું ૨૩ દિવસનું એકલાનું કામ = ૨૩ × ૯ = ૨૦૭. શરૂઆતનું ભેગું કામ = ૩૬૦ - ૨૦૭ = ૧૫૩. અમન અને ચંદનની ભેગી ક્ષમતા = ૧૭. દિવસો = ૧૫૩ / ૧૭ = ૯ દિવસ."},{"question_number":32,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"કામ પૂરું થવાના x દિવસ પહેલાં છોડી જવું (CCE 2023)","question_text":"R એકલો 24 દિવસમાં કામ પૂર્ણ કરી શકે છે અને S એકલો એ જ કામ 96 દિવસમાં પૂર્ણ કરી શકે છે. તેઓએ સાથે મળીને કામ શરૂ કર્યું, પરંતુ S એ કામ પૂરું થવાના 19 દિવસ પહેલા જ કામ છોડી દીધું. તો હવે કેટલા દિવસમાં કામ પૂરું થશે?","options":{"A":"27 દિવસ","B":"23 દિવસ","C":"35 દિવસ","D":"32 દિવસ"},"correct_answer":"B","explanation":"૨૪ અને ૯૬ નો લસાઅ = ૯૬. R = ૪, S = ૧. છેલ્લા ૧૯ દિવસ R એકલો કામ કરશે: ૧૯ × ૪ = ૭૬. બાકી કામ = ૯૬ - ૭૬ = ૨૦. શરૂઆતમાં બંને ભેગા મળીને કામ કરે છે: ૨૦ / ૫ = ૪ દિવસ. કુલ સમય = ૪ + ૧૯ = ૨૩ દિવસ."},{"question_number":33,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"કામ પૂરું થવાના પહેલાં છોડી જવું (CCE 2023)","question_text":"પૂજા અને રિયા 10 દિવસમાં એક કામ પૂર્ણ કરી શકે છે. રિયા એકલી 30 દિવસમાં એ જ કામ પૂર્ણ કરી શકતી હતી. તેઓએ સાથે કામ કરવાનું શરૂ કર્યું પરંતુ પૂજા કામ પૂરું થવાના 2 દિવસ પહેલા જ નીકળી ગઈ. કાર્ય પૂર્ણ કરવા માટે કુલ દિવસોની સંખ્યા શોધો.","options":{"A":"28/3 દિવસો","B":"22/3 દિવસો","C":"34/3 દિવસો","D":"10 દિવસો"},"correct_answer":"C","explanation":"લસાઅ = ૩૦. પૂજા+રિયા = ૩, રિયા = ૧ ⇒ પૂજા = ૨. પૂજા ૨ દિવસ પહેલાં ગઈ તેને ઉમેરી દો: ૨ × ૨ = ૪. નવું કુલ કામ = ૩૦ + ૪ = ૩૪. કુલ સમય = ૩૪ / ૩ દિવસ."},{"question_number":34,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"જટિલ ત્રિપદી કામ છોડવાના કોયડા (CCE 2023)","question_text":"P અને Q મળીને 36 દિવસમાં એક કાર્ય કરી શકે છે. Q અને R બંને ભેગા મળીને સમાન કાર્ય (360/7) દિવસમાં કરી શકે છે. P કાર્ય શરૂ કરે છે અને 24 દિવસ સુધી તેના પર કાર્ય કરે છે અને પછી તે કાર્યને છોડે છે. તેના પછી Q કાર્ય હાથમાં લે છે અને 42 દિવસ સુધી કાર્ય કરે છે અને પછી તે કાર્યને છોડે છે. અંતે R બાકી રહેલા કાર્યને 16 દિવસમાં પૂરું કરે છે. એકલો Q કેટલા દિવસમાં સમગ્ર કાર્યને પૂર્ણ કરી શકશે?","options":{"A":"120 દિવસ","B":"60 દિવસ","C":"90 દિવસ","D":"80 દિવસ"},"correct_answer":"C","explanation":"કુલ કાર્ય = ૩૬૦. P+Q ની ક્ષમતા = ૧૦, Q+R ની ક્ષમતા = ૭. P નું ૨૪ દિવસનું કામ + Q નું ૪૨ દિવસનું કામ + R નું ૧૬ દિવસનું કામ = ૨૪(P+Q) + ૧૮(Q+R) - ૨R = ૨૪(૧૦) + ૧૮(૭) - ૨R = ૨૪૦ + ૧૨૬ - ૨R = ૩૬૬ - ૨R = ૩૬૦ ⇒ ૨R = ૬ ⇒ R = ૩. તેથી Q ની ક્ષમતા = ૭ - ૩ = ૪. Q નો સમય = ૩૬૦ / ૪ = ૯૦ દિવસ."},{"question_number":35,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"કાર્યક્ષમતાની તુલના (Efficiency Comparison - CCE 2023)","question_text":"એમ્માએ પ્રોજેક્ટનો 3/4 ભાગ પૂર્ણ કર્યો જ્યારે નૂહે 70% ભાગ પૂર્ણ કર્યો. કોણે અન્યની સાપેક્ષે પ્રોજેક્ટનો વધારે ભાગ અને તે કેટલા ટકા કે હિસ્સાથી પૂર્ણ કર્યો છે?","options":{"A":"નૂહ, 1/4 જેટલો","B":"નૂહ, 5% જેટલો","C":"એમ્મા, 1/4 જેટલો","D":"એમ્મા, 5% જેટલો"},"correct_answer":"D","explanation":"૩/૪ = ૭૫%. નૂહ = ૭૦%. એમ્માએ ૫% વધારે ભાગ પૂર્ણ કર્યો."},{"question_number":36,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"ટકાવારી કાર્યક્ષમતા (Percentage Efficiency - CCE 2023)","question_text":"અશોકે 35 દિવસમાં સ્કૂલ પ્રોજેક્ટ પૂરો કર્યો. જો અજય અશોક કરતાં 25% વધુ કાર્યક્ષમ હોય તો તે જ કાર્ય પૂર્ણ કરવામાં કેટલા દિવસો લેશે?","options":{"A":"34 દિવસ","B":"48 દિવસ","C":"45 દિવસ","D":"28 દિવસ"},"correct_answer":"D","explanation":"કાર્યક્ષમતા અજય : અશોક = ૧૨૫ : ૧૦૦ = ૫ : ૪. સમયનો ગુણોત્તર = ૪ : ૫. ૫ એકમ = ૩૫ દિવસ ⇒ ૧ એકમ = ૭. અજયનો સમય = ૪ × ૭ = ૨૮ દિવસ."},{"question_number":37,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"ટકાવારી કાર્યક્ષમતા (CCE 2023)","question_text":"સુરેશ એક ચોક્કસ કામ 18 દિવસમાં કરી શકે છે. આશિષ સુરેશ કરતાં 80% વધુ કાર્યક્ષમ છે. એકલા આશિષને એ જ કામ કરવામાં કેટલા દિવસ લાગશે?","options":{"A":"15 દિવસ","B":"10 દિવસ","C":"12 દિવસ","D":"7 દિવસ"},"correct_answer":"B","explanation":"ક્ષમતા આશિષ : સુરેશ = ૧૮૦ : ૧૦૦ = ૯ : ૫. સમયનો ગુણોત્તર = ૫ : ૯. ૯ એકમ = ૧૮ દિવસ ⇒ ૧ એકમ = ૨. આશિષનો સમય = ૫ × ૨ = ૧૦ દિવસ."},{"question_number":38,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"ગુણાકાર કાર્યક્ષમતા (Multiple Efficiency - CCE 2023)","question_text":"X એ Y કરતાં ચાર ગણો સારો કારીગર છે અને સાથે મળીને તેઓ 20 દિવસમાં એક કામ પૂરું કરે છે. તો એકલો X કેટલા દિવસમાં કામ પૂરું કરશે?","options":{"A":"25 દિવસ","B":"21 દિવસ","C":"27 દિવસ","D":"20 દિવસ"},"correct_answer":"A","explanation":"ક્ષમતા X : Y = ૪ : ૧. કુલ ક્ષમતા = ૫. કુલ કામ = ૨૦ × ૫ = ૧૦૦ એકમ. X નો સમય = ૧૦૦ / ૪ = ૨૫ દિવસ."},{"question_number":39,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"ગુણાકાર કાર્યક્ષમતા (CCE 2023)","question_text":"બે કામદારો, A અને B સાથે મળીને એક કાર્ય 3 દિવસમાં પૂર્ણ કરી શકે છે. જો કામદાર A કામદાર B કરતાં બમણી ઝડપે કામ કરે છે અને તે બંને અચળ દરે કામ કરે છે, તો કામદાર A ને એકલા કાર્ય પૂર્ણ કરવામાં કેટલા દિવસો લાગશે?","options":{"A":"9 દિવસ","B":"12 દિવસ","C":"4.5 દિવસ","D":"6 દિવસ"},"correct_answer":"C","explanation":"ક્ષમતા A : B = ૨ : ૧. કુલ ક્ષમતા = ૩. કુલ કામ = ૩ × ૩ = ૯ એકમ. A નો સમય = ૯ / ૨ = ૪.૫ દિવસ."},{"question_number":40,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"ગુણોત્તર કાર્યક્ષમતા અને સમય તફાવત (CCE 2023)","question_text":"પૂર્ણિમા અનિતા કરતાં ત્રણ ગણી કાર્યક્ષમ છે અને કામ પૂર્ણ કરવામાં અનિતા કરતાં 32 દિવસ ઓછો સમય લે છે. તેઓ સાથે મળીને કેટલા દિવસમાં કામ પૂરું કરશે?","options":{"A":"24 દિવસ","B":"12 દિવસ","C":"21 દિવસ","D":"15 દિવસ"},"correct_answer":"B","explanation":"ક્ષમતા P : A = ૩ : ૧ ⇒ સમયનો ગુણોત્તર = ૧ : ૩. સમયનો તફાવત = ૨ એકમ = ૩૨ દિવસ ⇒ ૧ એકમ = ૧૬ દિવસ. P નો સમય = ૧૬, A નો સમય = ૪૮. લસાઅ = ૪૮. ભેગી ક્ષમતા = ૪. ભેગો સમય = ૪૮ / ૪ = ૧૨ દિવસ."},{"question_number":41,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"ત્રણ વ્યક્તિઓની ગુણોત્તર કાર્યક્ષમતા (CCE 2023)","question_text":"ત્રણ કામદારો, P, Q, અને R સાથે મળીને એક કાર્ય 4 દિવસમાં પૂર્ણ કરી શકે છે. કામદાર P કામદાર Q કરતાં બમણી ઝડપે કામ કરે છે અને કામદાર Q કામદાર R કરતાં બમણી ઝડપે કામ કરે છે. જો તેઓ બધા અચળ દરે કામ કરે, તો એકલા કામદાર Pને કાર્ય પૂર્ણ કરવામાં કેટલા દિવસો લાગશે?","options":{"A":"7 દિવસ","B":"10 દિવસ","C":"6 દિવસ","D":"8 દિવસ"},"correct_answer":"A","explanation":"ક્ષમતા P : Q : R = ૪ : ૨ : ૧. કુલ ક્ષમતા = ૭. કુલ કામ = ૪ × ૭ = ૨૮ એકમ. P નો સમય = ૨૮ / ૪ = ૭ દિવસ."},{"question_number":42,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"સમય તફાવત અને વ્યસ્ત ક્ષમતા (CCE 2023)","question_text":"A દ્વારા કામના ભાગને સમાપ્ત કરવામાં જે સમય લાગે છે તે B દ્વારા લેવામાં આવેલા સમય કરતાં બમણો અને C દ્વારા લેવાયેલા સમય કરતાં ત્રણ ગણો છે. જો તે ત્રણેય એકસાથે કામ કરે, તો તેમને સમગ્ર કાર્ય પૂર્ણ કરવામાં 4 દિવસનો સમય લાગે છે. તો એકલો B કેટલા દિવસમાં કામ પૂરું કરી શકે?","options":{"A":"14 દિવસ","B":"20 દિવસ","C":"18 દિવસ","D":"12 દિવસ"},"correct_answer":"D","explanation":"સમયનો ગુણોત્તર A : B : C = ૬ : ૩ : ૨. ક્ષમતાનો ગુણોત્તર A : B : C = ૧ : ૨ : ૩. કુલ ક્ષમતા = ૬. કુલ કામ = ૪ × ૬ = ૨૪. B નો સમય = ૨૪ / ૨ = ૧૨ દિવસ."},{"question_number":43,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"ચાર કામદારોની સંયુક્ત ક્ષમતા (CCE 2023)","question_text":"ચાર માળીઓ, A, B, C અને D સાથે મળીને કામ કરીને એક લેન્ડસ્કેપિંગ પ્રોજેક્ટને 6 દિવસમાં પૂર્ણ કરી શકે છે. માળી A, માળી D કરતાં ત્રણ ગણી ઝડપથી કામ કરે છે, માળી B, માળી D કરતાં બમણી ઝડપે કામ કરે છે, અને માળી C, માળી Dની ઝડપ જેટલી ઝડપથી કામ કરે છે. જો તેઓ બધા અચળ દરે કામ કરે, તો એકલા માળી Aને પ્રોજેક્ટ પૂર્ણ કરવામાં કેટલા દિવસો લાગશે?","options":{"A":"24","B":"14","C":"9","D":"18"},"correct_answer":"B","explanation":"ક્ષમતા A : B : C : D = ૩ : ૨ : ૧ : ૧. કુલ ક્ષમતા = ૭. કુલ કામ = ૬ × ૭ = ૪૨. A નો સમય = ૪૨ / ૩ = ૧૪ દિવસ."},{"question_number":44,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"મહેનતાણું અને વેતન (Wages - CCE 2023)","question_text":"એક કાર્ય પૂર્ણ કરવા માટે. અક્ષયને 6 દિવસ અને અજયને 8 દિવસનો સમય લાગે છે. અક્ષય અને અજયે આ કામ કરવા માટે ₹ 11200 લીધા હતા. સંજય જ્યારે તેમની સાથે જોડાયો ત્યારે કામ 3 દિવસમાં થઈ ગયું હતું. તો સંજયને કેટલી રકમ ચૂકવવામાં આવી?","options":{"A":"1400","B":"1450","C":"1560","D":"1600"},"correct_answer":"A","explanation":"૬, ૮ અને ૩ નો લસાઅ = ૨૪ (કુલ કામ). અક્ષયની ક્ષમતા = ૪, અજયની ક્ષમતા = ૩, ત્રણેયની ક્ષમતા (A+A+S) = ૮. સંજયની ક્ષમતા = ૮ - (૪ + ૩) = ૧. કુલ ૮ ભાગ = ₹ ૧૧૨૦૦ ⇒ ૧ ભાગ = ₹ ૧૪૦૦."},{"question_number":45,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"સાંકળનો નિયમ / ક્ષમતા ગુણોત્તર (Chain Rule - CCE 2023)","question_text":"6 પુરુષો અને 3 છોકરાઓ સાથે મળીને એક પુરુષ અને એક છોકરાની સરખામણીએ પાંચ ગણું વધારે કામ કરે છે. તો પુરુષ અને છોકરાની કામની ક્ષમતાનો ગુણોત્તર શોધો.","options":{"A":"2:1","B":"2:3","C":"2:4","D":"3:2"},"correct_answer":"A","explanation":"૬M + ૩C = ૫(૧M + ૧C) ⇒ ૬M + ૩C = ૫M + ૫C ⇒ ૧M = ૨C ⇒ M / C = ૨ / ૧."},{"question_number":46,"source":"સમય, કાર્ય અને વેતન Lecture 2.pdf","topic":"સાંકળનો નિયમ (Chain Rule - CCE 2023)","question_text":"12 મહિલાઓ એક કામ 5 દિવસમાં પૂર્ણ કરી શકે છે અને 15 બાળકોને કામ પૂર્ણ કરવામાં 10 દિવસ લાગે છે. 6 મહિલાઓ અને 10 બાળકો કામ પૂર્ણ કરવામાં કેટલા દિવસો લેશે?","options":{"A":"9 દિવસ","B":"6 દિવસ","C":"8 દિવસ","D":"10 દિવસ"},"correct_answer":"B","explanation":"૧૨W × ૫ = ૧૫C × ૧૦ ⇒ ૬૦W = ૧૫૦C ⇒ ૨W = ૫C (W/C = ૫/૨). કુલ કામ = ૬૦ × ૫ = ૩૦૦. ૬W + ૧૦C ની ક્ષમતા = ૬(૫) + ૧૦(૨) = ૫૦. સમય = ૩૦૦ / ૫૦ = ૬ દિવસ."}]},"pipes":{"subject":"Mathematics","chapter_title":"નળ અને ટાંકી (Pipes and Cisterns)","sources_included":["નળ અને ટાંકી.pdf"],"total_questions_count":45,"concept_notes":{"basic_concepts":["ઇનલેટ પાઇપ (Inlet Pipe): ટાંકી ભરવાનું કામ કરતી પાઇપનો દર ધન (+) ગણાય છે.","આઉટલેટ પાઇપ / લીકેજ (Outlet Pipe / Leakage): ટાંકી ખાલી કરતી પાઇપ અથવા ડ્રેઇનનો દર ઋણ (-) ગણાય છે.","કુલ ક્ષમતા (Total Capacity): સમયના લસાઅ (LCM) ને ટાંકીની કુલ ક્ષમતા તરીકે લેવામાં આવે છે.","કાર્યક્ષમતા (Efficiency): કાર્યક્ષમતા = કુલ ક્ષમતા / સમય."],"important_formulas":["જો પાઇપ A (a કલાક) અને પાઇપ B (b કલાક) બંને ભરે, તો બંને મળીને લાગતો સમય = (a × b) / (a + b)","જો પાઇપ A (a કલાક) ભરે અને પાઇપ B (b કલાક) ખાલી કરે, તો એકંદર સમય = (a × b) / (b - a)  (જ્યાં b > a)","લીકેજ વાળા કોયડા: નળ + લીકેજ = એકંદર દર."]},"questions":[{"question_number":1,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - સાદો સમય શોધો","question_text":"નળ P એક ડોલને 10 કલાકમાં ભરી શકે છે. નળ Q એ જ ડોલને 15 કલાકમાં ભરી શકે છે. જો બંને નળ એકસાથે ખોલવામાં આવે, તો ડોલ કેટલા કલાકમાં ભરાઈ જશે? (CCE 2023)","options":{"A":"4 કલાક","B":"7 કલાક","C":"5 કલાક","D":"6 કલાક"},"correct_answer":"D","explanation":"કુલ સમય = (10 × 15) / (10 + 15) = 150 / 25 = 6 કલાક."},{"question_number":2,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - સાદો સમય શોધો","question_text":"બે પાઇપો S અને T અનુક્રમે 3 કલાક અને 4 કલાકમાં ટાંકી ભરી શકે છે. જો બંને એકસાથે ખોલવામાં આવે, તો ટાંકી ભરવામાં લાગતો સમય શોધો. (CCE 2023)","options":{"A":"3 કલાક","B":"2 કલાક","C":"13/5 કલાક","D":"12/7 કલાક"},"correct_answer":"D","explanation":"કુલ સમય = (3 × 4) / (3 + 4) = 12/7 કલાક."},{"question_number":3,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - ભરણ + લીકેજ","question_text":"એક પંપ 3 કલાકમાં એક પૂલને ભરી શકે છે, અને લીકેજ 9 કલાકમાં તેને ખાલી કરી શકે છે. જો પંપ અને લીકેજ બંનેને આકસ્મિક રીતે ખુલ્લા છોડી દેવામાં આવે, તો પૂલને ભરાતા કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"6.75 કલાક","B":"4.5 કલાક","C":"7.5 કલાક","D":"9 કલાક"},"correct_answer":"B","explanation":"કુલ સમય = (9 × 3) / (9 - 3) = 27 / 6 = 4.5 કલાક."},{"question_number":4,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - ભરણ + ખાલી","question_text":"એક પાઇપ 4 કલાકમાં એક ટાંકીને ભરી શકે છે અને ડ્રેઇન પાઇપ 6 કલાકમાં આખી ટાંકી ખાલી કરી શકે છે. જો પાઇપ અને ડ્રેઇન પાઇપ બંને આકસ્મિક રીતે ખુલ્લા રહી જાય તો ટાંકી ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"24 કલાક","B":"10 કલાક","C":"7.2 કલાક","D":"12 કલાક"},"correct_answer":"D","explanation":"કુલ સમય = (6 × 4) / (6 - 4) = 24 / 2 = 12 કલાક."},{"question_number":5,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - ભરણ + લીકેજ","question_text":"એક પાઇપ 6 કલાકમાં ટાંકી ભરી શકે છે. જો કે, ટાંકીના તળિયે એક લીક છે જે 12 કલાકમાં સંપૂર્ણ ટાંકી ખાલી કરી શકે છે. જો ટાંકી ખાલી હોય અને પાઇપ અને લીક બંને ખુલ્લા હોય, તો ટાંકી ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"18 કલાક","B":"4.5 કલાક","C":"24 કલાક","D":"12 કલાક"},"correct_answer":"D","explanation":"કુલ સમય = (12 × 6) / (12 - 6) = 72 / 6 = 12 કલાક."},{"question_number":6,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - ભરણ + ખાલી","question_text":"પાણીની એક ટાંકીમાં બે પાઇપ હોય છે. પાઇપ A ટાંકી 2 કલાકમાં ભરી શકે છે, જ્યારે પાઇપ B 6 કલાકમાં સંપૂર્ણ ટાંકી ખાલી કરી શકે છે. જો ટાંકી ખાલી હોય ત્યારે બંને પાઇપ એક સાથે ખોલવામાં આવે તો ટાંકી ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"3 કલાક","B":"2.5 કલાક","C":"1.5 કલાક","D":"1 કલાક"},"correct_answer":"A","explanation":"કુલ સમય = (6 × 2) / (6 - 2) = 12 / 4 = 3 કલાક."},{"question_number":7,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - ભરણ + લીકેજ","question_text":"એક પાઇપ 6 કલાકમાં એક ટાંકી આખી ભરી શકે છે, જ્યારે કે ટાંકીનું તળિયું લીકેજ થવાથી 9 કલાકમાં આખી ટાંકી ખાલી થઈ શકે છે. જો પાઇપ અને લીકેજ બંને ખુલ્લા હોય તો આખી ટાંકી ભરવામાં કેટલો સમય લાગશે ? (CCE 2023)","options":{"A":"14 કલાક","B":"18 કલાક","C":"22 કલાક","D":"36 કલાક"},"correct_answer":"B","explanation":"કુલ સમય = (9 × 6) / (9 - 6) = 54 / 3 = 18 કલાક."},{"question_number":8,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - ભાગ ભરણ","question_text":"પાઇપ M દ્વારા એક ટાંકીને 12 કલાકમાં ભરી શકાય છે અને પાઇપ N દ્વારા 16 કલાકમાં ખાલી કરી શકાય છે. જો બંને પાઇપ એક સાથે ખોલવામાં આવે, તો ટાંકીને ત્રણ ચતુર્થાંશ ભરવા માટે લાગતો સમય શોધો. (CCE 2023)","options":{"A":"24 કલાક","B":"48 કલાક","C":"36 કલાક","D":"60 કલાક"},"correct_answer":"C","explanation":"આખી ટાંકીનો સમય = (16 × 12) / (16 - 12) = 48 કલાક. 3/4 ભાગ માટે = 48 × (3/4) = 36 કલાક."},{"question_number":9,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - અડધી ટાંકી","question_text":"ટાંકીને પાઇપ A દ્વારા 18 કલાકમાં ભરી શકાય છે અને પાઇપ B દ્વારા અનુક્રમે 20 કલાકમાં ખાલી કરી શકાય છે. તો ટાંકીને અડધી ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"82 કલાક","B":"90 કલાક","C":"45 કલાક","D":"50 કલાક"},"correct_answer":"B","explanation":"આખી ટાંકી = (20 × 18) / (20 - 18) = 180 કલાક. અડધી ટાંકી = 180 / 2 = 90 કલાક."},{"question_number":10,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - અડધી ટાંકી","question_text":"એક ટાંકી પાઇપ X દ્વારા 4 કલાકમાં ભરી શકાય છે અને પાઇપ Y દ્વારા 10 કલાકમાં ખાલી કરી શકાય છે. ટાંકીને અડધી ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"5.6 કલાક","B":"4.25 કલાક","C":"3.33 કલાક","D":"6.24 કલાક"},"correct_answer":"C","explanation":"આખી ટાંકી = (10 × 4) / (10 - 4) = 40 / 6 = 20/3 કલાક. અડધી ટાંકી = 20/3 / 2 = 10/3 = 3.33 કલાક."},{"question_number":11,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - અડધી ટાંકી (મિનિટ)","question_text":"એક ટાંકી પાઇપ X દ્વારા 4 કલાકમાં ભરી શકાય છે અને પાઇપ Y દ્વારા 10 કલાકમાં ખાલી કરી શકાય છે. જો બંને પાઇપ એકસાથે ખોલવામાં આવે તો ટાંકીને અડધી ભરાતા કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"4 કલાક 15 મિનિટ","B":"3 કલાક 20 મિનિટ","C":"5 કલાક 36 મિનિટ","D":"6 કલાક 14 મિનિટ"},"correct_answer":"B","explanation":"10/3 કલાક = 3 કલાક અને 1/3 કલાક (20 મિનિટ) = 3 કલાક 20 મિનિટ."},{"question_number":12,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - લીકેજ શોધો","question_text":"એક નળ 4 કલાકમાં એક કૂંડ આખો ભરી શકે છે. એક ખુલ્લી ડ્રેનેજ પાઇપને કારણે, આ કૂંડ ભરવામાં તેને 6 કલાકનો સમય લાગ્યો હતો. જો કૂંડ આખો ભરાયેલો હોય, તો એ ડ્રેનેજ પાઇપ તેને ખાલી કરવામાં કેટલો સમય લેશે? (CCE 2023)","options":{"A":"12 hrs","B":"16 hrs","C":"8 hrs","D":"24 hrs"},"correct_answer":"A","explanation":"લીકેજ સમય = (6 × 4) / (6 - 4) = 24 / 2 = 12 કલાક."},{"question_number":13,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - લીકેજ શોધો","question_text":"એક ઇલેક્ટ્રિક પંપ 5 કલાકમાં ટાંકી ભરી શકે છે. પરંતુ ટાંકીમાં લીકેજ થવાને કારણે, ટાંકી ભરવામાં 5.5 કલાકનો સમય લાગે છે. જો ટાંકી ભરાઈ ગઈ હોય, તો ટાંકીને લીકેજ દ્વારા ખાલી કરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"20 hrs","B":"30 hrs","C":"48 hrs","D":"55 hrs"},"correct_answer":"D","explanation":"લીકેજ સમય = (5 × 5.5) / (5.5 - 5) = 27.5 / 0.5 = 55 કલાક."},{"question_number":14,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - લીકેજ શોધો","question_text":"એક હોજ સામાન્ય રીતે 18 કલાકમાં ભરાય છે પરંતુ તેના તળિયે લીક થવાના કારણે તેને ભરાવવામાં બે કલાક વધુ સમય લાગે છે. જો હોજ ભરેલો હોય, તો લીક ના કારણે હોજને ખાલી થવામાં કેટલા કલાક લાગશે? (CCE 2023)","options":{"A":"150 hrs","B":"168 hrs","C":"180 hrs","D":"142 hrs"},"correct_answer":"C","explanation":"સામાન્ય સમય = 18, લીક સાથે સમય = 20 કલાક. લીક સમય = (20 × 18) / 2 = 180 કલાક."},{"question_number":15,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - ત્રણ પાઇપ","question_text":"ત્રણ પાઇપો A, B અને C એકસાથે કામ કરે તો 6 કલાકમાં એક ટાંકી ભરી શકે છે. પાઇપ A અને B સાથે મળીને તેને 10 કલાકમાં ભરી શકે છે. એકલી પાઇપ C ને ટાંકી ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"20 કલાક","B":"30 કલાક","C":"15 કલાક","D":"25 કલાક"},"correct_answer":"C","explanation":"C નો સમય = (10 × 6) / (10 - 6) = 60 / 4 = 15 કલાક."},{"question_number":16,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - બે પાઇપ","question_text":"પાઇપ P અને Q સાથે મળીને એક ટાંકી 4 કલાકમાં ભરી શકે છે. એકલો પાઇપ Q એક ટાંકીને 12 કલાકમાં ભરી શકે છે. એકલા પાઇપ P ને ટાંકી ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"12 કલાક","B":"8 કલાક","C":"4 કલાક","D":"6 કલાક"},"correct_answer":"D","explanation":"P નો સમય = (12 × 4) / (12 - 4) = 48 / 8 = 6 કલાક."},{"question_number":17,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - લસાઅ પદ્ધતિ","question_text":"ત્રણ પાઇપ્સ M, N અને O અનુક્રમે એક ટાંકીને 10, 15 અને 25 મીનીટમાં ભરી શકે છે. જો ત્રણેય પાઇપને એકસાથે ખોલવામાં આવે, તો ટાંકી ભરવામાં લાગતો સમય શોધો. (CCE 2023)","options":{"A":"150/31 મીનીટ","B":"17/7 મીનીટ","C":"111/31 મીનીટ","D":"15/7 મીનીટ"},"correct_answer":"A","explanation":"LCM(10, 15, 25) = 150. કાર્યક્ષમતાઓ = 15 + 10 + 6 = 31. સમય = 150/31 મિનિટ."},{"question_number":18,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - લસાઅ પદ્ધતિ (ખાલી પાઇપ)","question_text":"P એકલો 20 કલાકમાં ટાંકી ભરી શકે છે. Q એકલો એ જ ટાંકી 60 કલાકમાં ભરી શકે છે. R એકલો એ જ ટાંકી 30 કલાકમાં ખાલી કરી શકે છે. ત્રણેયને એકસાથે એ જ ટાંકી ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"30 કલાક","B":"40 કલાક","C":"25 કલાક","D":"35 કલાક"},"correct_answer":"A","explanation":"LCM(20, 60, 30) = 60. Net eff = 3 + 1 - 2 = 2. સમય = 60 / 2 = 30 કલાક."},{"question_number":19,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - લસાઅ પદ્ધતિ","question_text":"પાઇપ X અને Y અનુક્રમે 20 મિનિટ અને 30 મિનિટમાં એક ટાંકી ભરી શકે છે. પાઇપ Z ટાંકીને 25 મિનિટમાં ખાલી કરી શકે છે. જો બધી પાઇપો એકસાથે ખોલવામાં આવે, તો ટાંકી ભરવામાં કેટલો સમય લાગશે?. (CCE 2023)","options":{"A":"401/11 મિનિટ","B":"212/9 મિનિટ","C":"300/13 મિનિટ","D":"270/17 મિનિટ"},"correct_answer":"C","explanation":"LCM(20, 30, 25) = 300. Net eff = 15 + 10 - 12 = 13. સમય = 300/13 મિનિટ."},{"question_number":20,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - લસાઅ પદ્ધતિ","question_text":"સ્વિમિંગ પૂલમાં ત્રણ પાઇપ હોય છે. પાઇપ A પૂલને 4 કલાકમાં ભરી શકે છે, પરંતુ પાઇપ B તેને માત્ર 6 કલાકમાં ભરી શકે છે, પણ પાઇપ C લીક છે અને તે 12 કલાકમાં પૂલને ખાલી કરી શકે છે. જો ત્રણેય પાઇપો એક જ સમયે ખોલવામાં આવે, તો પૂલને સંપૂર્ણ રીતે ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"4.8 કલાક","B":"3 કલાક","C":"3.5 કલાક","D":"2.4 કલાક"},"correct_answer":"B","explanation":"LCM(4, 6, 12) = 12. Net eff = 3 + 2 - 1 = 4. સમય = 12 / 4 = 3 કલાક."},{"question_number":21,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - આઉટલેટ શોધો","question_text":"બે નળ A અને B અનુક્રમે 30 મિનિટ અને 36 મિનિટમાં એક ટાંકી ભરી શકે છે. જો આઉટલેટ નળ C ખોલવામાં આવે, તો ત્રણેય મળીને 60 મિનિટમાં એ ટાંકી ભરી શકે છે. એ જ ટાંકીને ખાલી કરવા માટે એકલા નળ C ને કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"45/2 મિનિટ","B":"53/4 મિનિટ","C":"45/4 મિનિટ","D":"53/3 મિનિટ"},"correct_answer":"A","explanation":"LCM(30, 36, 60) = 360. A=12, B=10, A+B-C=6. 12+10-C=6 => C=16. C નો સમય = 360/16 = 45/2 મિનિટ."},{"question_number":22,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - આઉટલેટ શોધો","question_text":"પાઇપ X અને Y અનુક્રમે 7 અને 14 કલાકમાં એક કૂંડને ભરી દે છે અને પાઇપ Z એક આઉટલેટ હોવાથી, તેઓ સાથે મળીને 28 કલાકમાં કૂંડ ભરી દે છે. એકલા Z ને સંપૂર્ણ કૂંડ ખાલી કરવામાં કેટલો સમય લાગશે ? (CCE 2023)","options":{"A":"5.6 કલાક","B":"4.7 કલાક","C":"3 કલાક","D":"5 કલાક"},"correct_answer":"A","explanation":"1/7 + 1/14 - 1/Z = 1/28 => 1/Z = 5/28 => Z = 28/5 = 5.6 કલાક."},{"question_number":23,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - આઉટલેટ શોધો","question_text":"બે નળ P અને Q અનુક્રમે 22.5 મિનિટ અને 27 મિનિટમાં એકલા ટાંકીને ભરી શકે છે. જો આઉટલેટ નળ R ખોલવામાં આવે, તો ત્રણેય મળીને 45 મિનિટમાં એક જ ટાંકી ભરી શકે છે. એ જ ટાંકી ખાલી કરવા માટે એકલા નળ R ને કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"135/8 મિનિટ","B":"125/3 મિનિટ","C":"135/4 મિનિટ","D":"125/4 મિનિટ"},"correct_answer":"A","explanation":"LCM(22.5, 27, 45) = 135. P=6, Q=5, P+Q-R=3 => R = 11 - 3 = 8. સમય = 135/8 મિનિટ."},{"question_number":24,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - જોડીદાર પાઇપ","question_text":"પાઇપ R અને S મળીને 120 કલાકમાં એક ટાંકી ભરી શકે છે. પાઇપ S અને C મળીને 60 કલાકમાં એ જ ટાંકીને ભરી શકે છે. પાઇપ R અને C એકસાથે 80 કલાકમાં એ જ ટાંકીને ભરી શકે છે. એકલી પાઇપ S કેટલા કલાકમાં એ જ ટાંકી ભરી શકે છે? (CCE 2023)","options":{"A":"180 કલાક","B":"150 કલાક","C":"170 કલાક","D":"160 કલાક"},"correct_answer":"D","explanation":"LCM = 240. R+S=2, S+C=4, R+C=3. 2(R+S+C) = 9 => R+S+C = 4.5. S = 4.5 - 3 = 1.5. સમય = 240 / 1.5 = 160 કલાક."},{"question_number":25,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - જોડીદાર પાઇપ","question_text":"પાઇપ A અને B એકસાથે મળીને 75 કલાકમાં એક ટાંકી ભરી શકે છે. પાઇપ B અને D એકસાથે 37.5 કલાકમાં સમાન ટાંકી ભરી શકે છે. પાઇપો A અને D એકસાથે મળીને આ જ ટાંકીને 50 કલાકમાં ભરી શકે છે. તો એકલા પાઇપ B કેટલા કલાકમાં આ જ ટાંકી ભરી શકશે? (CCE 2023)","options":{"A":"150 કલાક","B":"120 કલાક","C":"110 કલાક","D":"100 કલાક"},"correct_answer":"D","explanation":"LCM = 150. A+B=2, B+D=4, A+D=3. A+B+D = 4.5. B = 4.5 - 3 = 1.5. સમય = 150 / 1.5 = 100 કલાક."},{"question_number":26,"source":"નળ અને ટાંકી.pdf","topic":"Type 1 - દ્વિઘાત સોલ્યુશન શોર્ટકટ","question_text":"જો પાઇપ C એક ટાંકીને પાઇપ D કરતા 20 કલાક ધીમા દરે ભરી શકે છે. પાઇપ C અને D એકસાથે એ જ ટાંકીને 24 કલાકમાં ભરી શકે છે, તો એકલી ઝડપી પાઇપ કેટલા કલાકમાં ટાંકી ભરી શકે છે? (CCE 2023)","options":{"A":"50 કલાક","B":"30 કલાક","C":"20 કલાક","D":"40 કલાક"},"correct_answer":"D","explanation":"ઓપ્શન ટેસ્ટિંગ: D = 40 કલાક, C = 60 કલાક. ભેગા મળીને = (40 × 60) / 100 = 24 કલાક."},{"question_number":27,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - વચ્ચેથી નળ બંધ કરવો","question_text":"બે નળી, X અને Y, અનુક્રમે 5 કલાક અને 10 કલાકમાં પૂલ ભરી શકે છે. જો બંને નળી એક જ સમયે ખોલવામાં આવે છે પરંતુ નળી X 2 કલાક પછી બંધ કરવામાં આવે છે, તો પૂલને પૂર્ણ રીતે ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"6 કલાક","B":"5 કલાક","C":"4 કલાક","D":"4.5 કલાક"},"correct_answer":"A","explanation":"LCM = 10. Eff X=2, Y=1. X એ 2 કલાકમાં 2×2 = 4 એકમ કર્યા. બાકી 6 એકમ Y એકલો કરશે: 6/1 = 6 કલાક."},{"question_number":28,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - વચ્ચેથી નળ બંધ કરવો","question_text":"બે પાઇપો A અને D અનુક્રમે 32 કલાક અને 40 કલાકમાં એકલી ટાંકી ભરી શકે છે. જો બંને પાઇપ એકસાથે ખોલવામાં આવે તો કેટલા સમય પછી પાઇપ D બંધ કરવી જોઈએ જેથી ટાંકી 25 કલાકમાં ભરાઈ જાય? (CCE 2023)","options":{"A":"35/4 કલાક","B":"31/7 કલાક","C":"31/4 કલાક","D":"33/4 કલાક"},"correct_answer":"A","explanation":"LCM = 320. Eff A=10, D=8. A સતત 25 કલાક ચાલુ રહે છે: 25 × 10 = 250. બાકી 70 એકમ D કરશે: 70/8 = 35/4 કલાક."},{"question_number":29,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - વચ્ચેથી નળ બંધ કરવો","question_text":"બે નળ S અને T એક ટાંકીને અનુક્રમે 36 મિનિટ અને 48 મિનિટમાં ભરે છે. જો બંને નળ એકસાથે ખોલવામાં આવે, તો કેટલી મિનિટ પછી નળ T ને બંધ કરવો જોઈએ જેથી ટાંકી 24 મિનિટમાં ભરાઈ જાય? (CCE 2023)","options":{"A":"28 મિનિટ","B":"20 મિનિટ","C":"24 મિનિટ","D":"16 મિનિટ"},"correct_answer":"D","explanation":"LCM = 144. Eff S=4, T=3. S ચાલુ રહે છે 24 મિનિટ: 24 × 4 = 96. બાકી 48 એકમ T કરશે: 48/3 = 16 મિનિટ."},{"question_number":30,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - વચ્ચેથી નળ બંધ કરવો","question_text":"બે નળ G અને H અનુક્રમે 24 મિનિટ અને 32 મિનિટમાં એક ટાંકી ભરે છે. જો બંને નળ એકસાથે ખોલવામાં આવે, તો કેટલી મિનિટ પછી નળ H બંધ કરવો જોઈએ જેથી ટાંકી 16 મિનિટમાં ભરાઈ જાય. (CCE 2023)","options":{"A":"15.36 મિનિટ","B":"14.5 મિનિટ","C":"10.66 મિનિટ","D":"16.24 મિનિટ"},"correct_answer":"C","explanation":"LCM = 96. Eff G=4, H=3. G એ 16 મિનિટમાં 64 એકમ કામ કર્યું. બાકી 32 એકમ H કરશે: 32/3 = 10.66 મિનિટ."},{"question_number":31,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - બાકીનું કામ","question_text":"બે પાઇપો A અને B અનુક્રમે 20 મિનિટ અને 60 મિનિટમાં એક ટાંકીને ભરી શકે છે. તેમને એકસાથે ખોલવામાં આવે છે પરંતુ થોડા સમય પછી, પાઇપ B બંધ કરવામાં આવે છે, અને પાઇપ A બાકીની ટાંકી વધુ 8 મિનિટમાં ભરે છે. શરૂઆત થયાની કેટલી મિનિટ પછી પાઇપ B બંધ કરવામાં આવી હતી? (CCE 2023)","options":{"A":"9 મિનિટ","B":"14 મિનિટ","C":"6 મિનિટ","D":"12 મિનિટ"},"correct_answer":"A","explanation":"LCM = 60. Eff A=3, B=1. પાછળથી A એકલાએ 8 મિનિટમાં 8×3 = 24 કામ કર્યું. બાકી 36 કામ સાથે કર્યું હતું: 36 / (3+1) = 9 મિનિટ."},{"question_number":32,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - મોડી શરૂઆત પાઇપ","question_text":"બે પાઇપો A1 અને A2 અનુક્રમે 21 કલાક અને 28 કલાકમાં ખાલી ટાંકીને ભરી શકે છે. પાઇપ A3 એકલી 56 કલાકમાં સંપૂર્ણપણે ભરેલી ટાંકીને ખાલી કરી શકે છે. સૌપ્રથમ A1 અને A2 બંને પાઇપ ખોલવામાં આવે છે અને 5 કલાક પછી A3 પાઇપ પણ ખોલવામાં આવે છે. તો કેટલા સમયમાં ટાંકી સંપૂર્ણપણે ભરાશે? (CCE 2023)","options":{"A":"168/7 કલાક","B":"165/8 કલાક","C":"153/11 કલાક","D":"157/13 કલાક"},"correct_answer":"C","explanation":"LCM = 168. A1=8, A2=6, A3=-3. પ્રથમ 5 કલાકમાં A1+A2 = (8+6)×5 = 70. બાકી 98 એકમ ત્રણેય સાથે: 98/11. કુલ સમય = 5 + 98/11 = 153/11 કલાક."},{"question_number":33,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - મોડી શરૂઆત પાઇપ","question_text":"બે પાઇપો P અને Q એક ખાલી ટાંકીને અનુક્રમે 30 કલાક અને 36 કલાકમાં ભરી શકે છે. પાઇપ R એકલી 45 કલાકમાં સંપૂર્ણ ભરેલી ટાંકીને ખાલી કરી શકે છે. સૌપ્રથમ P અને Q બંને પાઇપ ખોલવામાં આવે છે અને 10 કલાક પછી પાઇપ R પણ ખોલવામાં આવે છે. તો કુલ કેટલા સમયમાં ટાંકી ભરાઈ જશે? (CCE 2023)","options":{"A":"25 કલાક","B":"35 કલાક","C":"30 કલાક","D":"20 કલાક"},"correct_answer":"D","explanation":"LCM = 180. Eff P=6, Q=5, R=-4. પ્રથમ 10 કલાકમાં P+Q = (6+5)×10 = 110. બાકી 70 એકમ ત્રણેય કરશે: 70/7 = 10. કુલ સમય = 10 + 10 = 20 કલાક."},{"question_number":34,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - આશરે સમય","question_text":"ત્રણ પાઇપો, P1, P2 અને P3 એક પૂલને ભરે છે. એકલી P1 ને 2 કલાક લાગે છે, એકલી P2 એ 5 કલાક લે છે, અને એકલી P3 એ 10 કલાક લે છે. હવે જો પાઇપ P3 શરૂઆતના 1 કલાક પછી કામ કરવાનું બંધ કરે છે, તો પૂલ ભરવામાં કુલ કેટલો સમય લાગશે? (આશરે) (CCE 2023)","options":{"A":"2 કલાક અને 15 મિનિટ","B":"1 કલાક અને 17 મિનિટ","C":"3 કલાક","D":"2 કલાક અને 45 મિનિટ"},"correct_answer":"B","explanation":"LCM = 10. Eff P1=5, P2=2, P3=1. 1 કલાકમાં ત્રણેય = 8 એકમ. બાકી 2 એકમ P1+P2 કરશે: 2/7 કલાક. કુલ સમય = 1 કલાક 17 મિનિટ."},{"question_number":35,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - મોડી શરૂઆત પાઇપ","question_text":"બે પાઇપો G અને H એક ખાલી ટાંકીને અનુક્રમે 40 કલાક અને 48 કલાકમાં ભરી શકે છે. એકલી પાઇપ T તે સંપૂર્ણ ભરેલી ટાંકીને 60 કલાકમાં ખાલી કરી શકે છે. સૌપ્રથમ, G અને H બંને પાઇપ ખોલવામાં આવે છે અને 18 કલાક પછી પાઇપ T પણ ખોલવામાં આવે છે. તો (અંદાજે) કુલ કેટલા સમયમાં ટાંકી ભરાઈ જશે? (CCE 2023)","options":{"A":"26 કલાક","B":"24 કલાક","C":"28 કલાક","D":"32 કલાક"},"correct_answer":"B","explanation":"LCM = 240. Eff G=6, H=5, T=-4. 18 કલાકમાં G+H = 11×18 = 198. બાકી 42 એકમ ત્રણેય કરશે: 42/7 = 6 કલાક. કુલ સમય = 18 + 6 = 24 કલાક."},{"question_number":36,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - મિનિટ રૂપાંતરણ","question_text":"જો નળ X 6 કલાકમાં, નળ Y 9 કલાકમાં અને નળ Z 18 કલાકમાં એક સ્વિમિંગ પૂલને ભરી શકે છે, જેમાં 2 કલાકની કામગીરી પછી નળ Z ને બંધ કરવામાં આવે છે, તો બાકી રહેલ સ્વિમિંગ પૂલ ભરવા માટે બંને નળ X અને Y કેટલો સમય લેશે? (CCE 2023)","options":{"A":"192 મિનિટ","B":"240 મિનિટ","C":"180 મિનિટ","D":"270 મિનિટ"},"correct_answer":"A","explanation":"LCM = 18. Eff X=3, Y=2, Z=1. 2 કલાકમાં ત્રણેય = (3+2+1)×2 = 12. બાકી 6 એકમ X+Y કરશે: 6/5 કલાક = 1.2 કલાક = 192 મિનિટ (કુલ 3.2 કલાક = 192 મિનિટ)."},{"question_number":37,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - એકાંતર કલાકો","question_text":"પાઇપ P 60 કલાકમાં એક ટાંકીને ભરી શકે છે અને પાઇપ Q 90 કલાકમાં તે ટાંકીને ભરી શકે છે. જો બંને પાઇપોને એક સમયે એક એમ એકાંતર કલાકોએ ખોલવામાં આવે, અને પાઇપ Q ને પ્રથમ કલાક માટે ખોલવામાં આવે, તો ટાંકી કેટલા સમયમાં સંપૂર્ણ ભરાઈ જશે? (CCE 2023)","options":{"A":"68 કલાક","B":"71 કલાક","C":"72 કલાક","D":"75 કલાક"},"correct_answer":"C","explanation":"LCM = 180. Eff P=3, Q=2. 2 કલાકમાં 5 એકમ કામ થાય છે. 180 એકમ માટે = (180 / 5) × 2 = 72 કલાક."},{"question_number":38,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - મોડી શરૂઆત","question_text":"એક ટાંકીને બે પાઇપો A અને B દ્વારા અનુક્રમે 5 અને 6 કલાકમાં ભરી શકાય છે. ત્રીજી પાઇપ C આખી ટાંકી 10 કલાકમાં ખાલી કરી શકે છે. ટાંકી ભરવા માટે પાઇપ A અને B એકસાથે ખોલવામાં આવે છે, પરંતુ 2 કલાક પછી પાઇપ C પણ ખોલવામાં આવે છે, ટાંકી ભરવામાં કુલ કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"3 કલાક અને 45 મિનિટ","B":"4 કલાક","C":"4 કલાક અને 30 મિનિટ","D":"3 કલાક"},"correct_answer":"D","explanation":"LCM = 30. Eff A=6, B=5, C=-3. 2 કલાકમાં A+B = 22. બાકી 8 એકમ ત્રણેય કરશે: 8/8 = 1 કલાક. કુલ સમય = 2 + 1 = 3 કલાક."},{"question_number":39,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - શરતી નળ બંધ","question_text":"જો પંપ A ટાંકીને 4 કલાકમાં, પંપ B 6 કલાકમાં અને પંપ C 12 કલાકમાં ટાંકી ભરી શકે છે, તે એવી શરત સાથે કે પંપ C ખોલ્યાના 2 કલાક પછી કામ કરવાનું બંધ કરી દે છે તો ત્રણ પંપ A, B અને C નો ઉપયોગ કરીને ટાંકી ભરવા માટે કેટલો સમય જરૂરી છે? (CCE 2023)","options":{"A":"2 કલાક અને 32 મિનિટ","B":"2 કલાક અને 48 મિનિટ","C":"2 કલાક અને 12 મિનિટ","D":"2 કલાક"},"correct_answer":"D","explanation":"LCM = 12. Eff A=3, B=2, C=1. C એ 2 કલાકમાં 2×1 = 2 એકમ કર્યા. બાકી 10 એકમ A+B કરશે: 10/5 = 2 કલાક."},{"question_number":40,"source":"નળ અને ટાંકી.pdf","topic":"Type 2 - પ્રવાહી પ્રમાણ ગુણોત્તર","question_text":"ત્રણ પાઇપ્સ A, B અને C એક ખાલી ટાંકીને અનુક્રમે 18 મીનીટમાં, 12 મીનીટમાં, અને 10 મીનીટમાં પૂરી ભરી દે છે. ટાંકી જ્યારે ખાલી હોય ત્યારે એ ત્રણેય પાઇપ્સને ખુલ્લા કરવામાં આવે છે. A, B અને C માંથી અનુક્રમે કેમિકલ પ્રવાહી P, Q અને R છોડવામાં આવે છે. 3 મીનીટ બાદ ટાંકીમાં R ના પ્રવાહીનું પ્રમાણ કેટલું હશે? (CCE 2023)","options":{"A":"6:8","B":"43:57","C":"18:35","D":"18:43"},"correct_answer":"D","explanation":"LCM = 180. Eff P=10, Q=15, R=18. કુલ ક્ષમતા દર મિનિટે = 43. 3 મિનિટમાં R નું પ્રમાણ = 18 / 43."},{"question_number":41,"source":"નળ અને ટાંકી.pdf","topic":"Type 3 - કાર્યક્ષમતા (Efficiency)","question_text":"પાઇપ A, પાઇપ B ની સરખામણીમાં 3 ગણી ઝડપથી ટાંકી ભરી શકે છે. પાઇપ A અને B ને ભેગા મળીને ટાંકી ભરવામાં 42 મિનિટ લાગે છે. એકલા પાઇપ B ને ટાંકી ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"168 મિનિટ","B":"145 મિનિટ","C":"106 મિનિટ","D":"99 મિનિટ"},"correct_answer":"A","explanation":"ગુણોત્તર A:B = 3:1. કુલ કાર્યક્ષમતા = 4. કુલ કામ = 42 × 4 = 168. B નો સમય = 168 / 1 = 168 મિનિટ."},{"question_number":42,"source":"નળ અને ટાંકી.pdf","topic":"Type 3 - કાર્યક્ષમતા","question_text":"એક નળ બીજા નળ કરતાં છ ગણી ઝડપથી એક ટાંકી ભરી શકે છે. જો એકસાથે બે નળ 40 મિનિટમાં ટાંકીને ભરી શકે છે, તો એકલો ધીમો નળ ટાંકીને કેટલા સમયમાં ભરી શકશે? (CCE 2023)","options":{"A":"420 મિનિટ","B":"280 મિનિટ","C":"350 મિનિટ","D":"210 મિનિટ"},"correct_answer":"B","explanation":"ઝડપી : ધીમો = 6 : 1. કુલ કાર્યક્ષમતા = 7. કુલ કામ = 40 × 7 = 280. ધીમો નળ = 280 / 1 = 280 મિનિટ."},{"question_number":43,"source":"નળ અને ટાંકી.pdf","topic":"Type 3 - કાર્યક્ષમતા","question_text":"નળ A એ નળ B કરતા સાત ગણી ઝડપથી એક ટાંકીને ભરી શકે છે. જો બે નળ મળીને 37 મિનિટમાં ટાંકી ભરી શકે છે, તો એકલો નળ B કેટલી મિનિટમાં ટાંકી ભરી શકશે? (CCE 2023)","options":{"A":"296 મિનિટ","B":"300 મિનિટ","C":"320 મિનિટ","D":"288 મિનિટ"},"correct_answer":"A","explanation":"A : B = 7 : 1. કુલ કાર્યક્ષમતા = 8. કુલ કામ = 37 × 8 = 296. B નો સમય = 296 મિનિટ."},{"question_number":44,"source":"નળ અને ટાંકી.pdf","topic":"Type 3 - ત્રિપદી ગુણોત્તર કાર્યક્ષમતા","question_text":"એક પૂલ 4 કલાકમાં ત્રણ નળી X, Y અને Z દ્વારા ભરવામાં આવે છે. નળી Z એ Y કરતા ત્રણ ગણી ઝડપી છે, અને Y એ X કરતા ત્રણ ગણી ઝડપી છે. એકલી X નળીને પૂલ ભરવામાં કેટલો સમય લાગશે? (CCE 2023)","options":{"A":"48 hrs","B":"52 hrs","C":"24 hrs","D":"36 hrs"},"correct_answer":"B","explanation":"X : Y : Z = 1 : 3 : 9. કુલ કાર્યક્ષમતા = 13. કુલ કામ = 4 × 13 = 52. X નો સમય = 52 / 1 = 52 કલાક."},{"question_number":45,"source":"નળ અને ટાંકી.pdf","topic":"Type 4 - ટાંકીની ક્ષમતા (Capacity)","question_text":"બે પાઇપ એક ટાંકીને અનુક્રમે 40 કલાક અને 48 કલાકમાં ભરી શકે છે અને એક આઉટલેટ પાઇપ કલાક દીઠ 10 ગેલન પાણી ખાલી કરી શકે છે. એકસાથે ત્રણેય પાઇપો ખાલી ટાંકીને 40 કલાકમાં ભરી શકે છે. તો ટાંકીની ક્ષમતા કેટલી હશે? (CCE 2023)","options":{"A":"480 ગેલન","B":"400 ગેલન","C":"500 ગેલન","D":"540 ગેલન"},"correct_answer":"A","explanation":"LCM = 240. A=6, B=5, A+B-C=6 => C = 5. C નો સમય = 240/5 = 48 કલાક. ક્ષમતા = 48 × 10 = 480 ગેલન."}]}};
 const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const titleMap={chain:'સાંકળનો નિયમ · MDH',work:'સમય, કાર્ય અને વેતન',pipes:'નળ અને ટાંકી'};
 const subMap={chain:'CHAIN RULE',work:'TIME · WORK · WAGES',pipes:'PIPES · CISTERNS'};
 const chapters=[{key:'chain',data:SOURCE.chain},{key:'work',data:SOURCE.work},{key:'pipes',data:SOURCE.pipes}];
 function note(id, title, lines){N[id]=Array.isArray(N[id])?N[id]:[];if(!N[id].some(x=>x[0]===title))N[id].push([title,lines]);}

 /* ---------- tiny text formatter: **bold**, [[chip]], ~eq lines ---------- */
 const fm=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\[\[(.+?)\]\]/g,'<span class="mx-chip">$1</span>').replace(/\{\{(.+?)\}\}/g,'<span class="mx-hl">$1</span>');
 const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
 const icons=(e,n,max)=>{max=max||12;const k=Math.min(n,max);let s='';for(let i=0;i<k;i++)s+=e;if(n>max)s+=`<small class="mx-more">+${n-max}</small>`;return s;};
 /* ---------- self-contained styles (prefix mx-) ---------- */
 const CSS=`
.mx-sol,.mx-nv,.mx-strip{--ink:#1f2937;--mut:#6b7280;--paper:#fffdf8;--line:#e8e2d4;--ac:#2563eb;--acs:#eaf1ff;--ok:#15803d;--oks:#e8f7ee;--bad:#b91c1c;--bads:#fdeeee;--warn:#92400e;--warns:#fff5e0;box-sizing:border-box;font-family:'Noto Sans Gujarati','Hind Vadodara','Shruti',system-ui,-apple-system,'Segoe UI',sans-serif;color:var(--ink);line-height:1.5;text-align:left}
.mx-sol *,.mx-nv *,.mx-strip *{box-sizing:border-box}
.mx-c-chain{--ac:#2563eb;--acs:#eaf1ff}.mx-c-work{--ac:#c2410c;--acs:#fff0e4}.mx-c-pipes{--ac:#0e7490;--acs:#e3f6fb}
.mx-sol{background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:14px 12px 12px;margin:8px 0;box-shadow:0 2px 10px rgba(60,50,20,.08);overflow:hidden;max-width:100%}
.mx-head{display:flex;gap:10px;align-items:flex-start;justify-content:space-between;margin-bottom:10px}
.mx-head small{display:block;font-size:10.5px;letter-spacing:.08em;font-weight:700;color:var(--ac)}
.mx-head h3{margin:2px 0 0;font-size:15.5px;line-height:1.35;color:var(--ink);font-weight:800}
.mx-qno{flex:none;min-width:42px;height:42px;border-radius:12px;background:var(--ac);color:#fff;font-weight:800;font-size:17px;display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1}
.mx-qno small{color:#fff;opacity:.8;font-size:9px;letter-spacing:.1em;margin-top:2px}
.mx-gf{display:grid;gap:6px;margin:8px 0}
.mx-row{display:flex;gap:6px;flex-wrap:wrap;align-items:center;font-size:13px}
.mx-row>label{flex:none;font-weight:800;font-size:12px;color:var(--mut)}
.mx-pill{display:inline-block;background:#fff;border:1px solid var(--line);border-radius:999px;padding:2px 10px;font-size:12.5px;font-weight:700}
.mx-pill.f{background:var(--acs);border-color:transparent;color:var(--ac)}
.mx-chip{display:inline-block;background:var(--acs);color:var(--ac);border-radius:7px;padding:0 7px;font-weight:800;white-space:nowrap}
.mx-hl{background:linear-gradient(transparent 55%,#ffe27a 55%);font-weight:800;padding:0 2px}
.mx-idea{display:flex;gap:8px;background:var(--acs);border-radius:12px;padding:9px 11px;margin:10px 0;font-size:13.5px}
.mx-idea>span{font-size:18px;line-height:1.2}
.mx-vis{background:#fff;border:1px solid var(--line);border-radius:14px;padding:10px 8px;margin:10px 0}
.mx-vis+.mx-vis{margin-top:8px}
.mx-cap{font-size:11.5px;color:var(--mut);text-align:center;margin-top:6px;font-weight:600}
.mx-vt{font-size:11px;font-weight:800;letter-spacing:.06em;color:var(--mut);text-align:center;margin-bottom:6px;text-transform:uppercase}
.mx-svg{display:block;width:100%;height:auto;max-width:420px;margin:0 auto}
.mx-svg text{font-family:inherit}
.mx-steps{margin:12px 0 4px;position:relative}
.mx-step{display:flex;gap:10px;position:relative;padding-bottom:12px}
.mx-step:before{content:'';position:absolute;left:13px;top:28px;bottom:0;width:2px;background:repeating-linear-gradient(var(--line) 0 4px,transparent 4px 8px)}
.mx-step:last-child:before{display:none}
.mx-no{flex:none;width:28px;height:28px;border-radius:50%;background:#fff;border:2px solid var(--ac);color:var(--ac);font-weight:800;font-size:13px;display:flex;align-items:center;justify-content:center;z-index:1}
.mx-sb{flex:1;min-width:0}
.mx-sb h4{margin:3px 0 3px;font-size:14px;font-weight:800;color:var(--ink)}
.mx-sb p{margin:2px 0;font-size:13.5px;overflow-wrap:anywhere}
.mx-eq{background:#f6f3ea;border-left:3px solid var(--ac);border-radius:6px;padding:4px 9px;margin:4px 0;font-weight:700;font-size:13.5px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.mx-res{background:var(--oks);border-left:3px solid var(--ok);color:#14532d;border-radius:6px;padding:4px 9px;margin:4px 0;font-weight:800;font-size:13.5px;overflow-wrap:anywhere}
.mx-ans{display:flex;gap:10px;align-items:center;background:var(--oks);border:1.5px solid #86d3a3;border-radius:14px;padding:10px 12px;margin:8px 0}
.mx-ans>b{flex:none;width:34px;height:34px;border-radius:50%;background:var(--ok);color:#fff;display:flex;align-items:center;justify-content:center;font-size:16px}
.mx-ans small{display:block;font-size:10.5px;letter-spacing:.08em;font-weight:800;color:#166534}
.mx-ans strong{font-size:17px;color:#14532d;line-height:1.3}
.mx-opts{display:flex;gap:5px;flex-wrap:wrap;margin:6px 0}
.mx-opt{font-size:12px;padding:2px 9px;border-radius:8px;border:1px solid var(--line);background:#fff;color:var(--mut);font-weight:700}
.mx-opt.ok{background:var(--ok);border-color:var(--ok);color:#fff}
.mx-tip,.mx-trap,.mx-chk{display:flex;gap:8px;border-radius:12px;padding:8px 11px;margin:7px 0;font-size:13px}
.mx-tip{background:#eef9f1;border:1px dashed #86d3a3}.mx-trap{background:var(--warns);border:1px dashed #f0b45a;color:var(--warn)}.mx-chk{background:#f3f4f8;border:1px dashed #b9bfd4}
.mx-note{background:var(--bads);border:1px solid #f2b3b3;color:#7f1d1d;border-radius:12px;padding:8px 11px;margin:8px 0;font-size:12.5px}
.mx-cards{display:flex;gap:6px;align-items:stretch}
.mx-card{flex:1;min-width:0;background:#fbfaf5;border:1.5px solid var(--line);border-radius:12px;padding:8px;text-align:center}
.mx-card.b{border-color:var(--ac);background:var(--acs)}
.mx-card-t{font-size:11px;font-weight:800;color:var(--mut);margin-bottom:3px}
.mx-ico{font-size:17px;line-height:1.25;min-height:22px;word-break:break-all}
.mx-more{font-size:11px;color:var(--mut);font-weight:700;vertical-align:middle}
.mx-kv{display:grid;grid-template-columns:1fr auto;gap:1px 8px;font-size:12.5px;text-align:left;margin-top:5px}
.mx-kv span{color:var(--mut)}.mx-kv b{text-align:right}
.mx-big{margin-top:6px;font-size:19px;font-weight:800;color:var(--ac)}
.mx-big small{display:block;font-size:10.5px;color:var(--mut);font-weight:700}
.mx-mid{flex:none;align-self:center;font-weight:800;font-size:18px;color:var(--ac)}
.mx-bar-wrap{margin:2px 0 4px}
.mx-bar-t{font-size:12px;font-weight:800;margin-bottom:4px}
.mx-bar{display:flex;border-radius:9px;overflow:hidden;border:1px solid rgba(0,0,0,.1);min-height:42px}
.mx-seg{flex-basis:0;flex-grow:1;min-width:46px;color:#fff;padding:4px 3px;text-align:center;display:flex;flex-direction:column;justify-content:center;border-right:1px solid rgba(255,255,255,.55);overflow:hidden}
.mx-seg:last-child{border-right:0}
.mx-seg b{font-size:12px;line-height:1.2;overflow-wrap:anywhere}.mx-seg small{font-size:10.5px;opacity:.95;line-height:1.2}
.mx-bar-f{font-size:11.5px;color:var(--mut);text-align:center;margin-top:4px;font-weight:600}
.mx-rate{display:flex;align-items:center;gap:6px;margin:4px 0}
.mx-rn{flex:none;width:82px;font-size:12.5px;font-weight:700;line-height:1.2}
.mx-sqs{flex:1;display:flex;flex-wrap:wrap;gap:2px;min-width:0}
.mx-sqs i{display:block;width:11px;height:11px;border-radius:3px}
.mx-sqs i.h{width:6px}
.mx-rate>b{flex:none;min-width:34px;text-align:right;font-size:13px}
.mx-rate.t{border-top:2px solid var(--ink);padding-top:5px;margin-top:6px}
.mx-rf{font-size:12.5px;font-weight:700;text-align:center;margin-top:7px;background:#f6f3ea;border-radius:8px;padding:5px}
.mx-flow{display:flex;flex-wrap:wrap;gap:5px;align-items:center;justify-content:center}
.mx-fb{background:var(--acs);border:1.5px solid var(--ac);border-radius:10px;padding:5px 9px;font-weight:800;font-size:13px;text-align:center}
.mx-fb small{display:block;font-size:10.5px;font-weight:600;color:var(--mut)}
.mx-fa{font-weight:800;color:var(--ac);font-size:13px;text-align:center}
.mx-cycle{display:flex;flex-wrap:wrap;gap:5px;justify-content:center}
.mx-cc{min-width:58px;background:#fff;border:2px solid var(--cc);border-radius:10px;text-align:center;padding:3px 5px}
.mx-cc small{display:block;font-size:10px;color:var(--mut);font-weight:700}.mx-cc b{display:block;font-size:14px;color:var(--cc)}.mx-cc span{font-size:12px;font-weight:700}.mx-cc em{display:block;font-style:normal;font-size:10.5px;color:var(--mut);border-top:1px dashed var(--line);margin-top:2px}
.mx-cgap{align-self:center;font-weight:800;color:var(--mut)}
.mx-tbl{width:100%;border-collapse:collapse;font-size:12.5px}
.mx-tbl th{background:#f1ede0;padding:5px 6px;font-size:11.5px;text-align:center}
.mx-tbl td{padding:5px 6px;border-bottom:1px solid var(--line);text-align:center;font-weight:600}
.mx-tbl tr.hi td{background:var(--oks);font-weight:800;color:#14532d}
.mx-vd{display:grid;gap:6px}
.mx-vd>div{display:flex;gap:8px;align-items:flex-start;border-radius:10px;padding:7px 9px;font-size:13px}
.mx-vd .y{background:var(--oks);border:1px solid #9bd7b3}.mx-vd .n{background:var(--bads);border:1px solid #f2b3b3}
.mx-vd b.m{flex:none;font-size:16px}
.mx-cmp{display:grid;gap:5px}
.mx-cmp>div{display:flex;align-items:center;gap:6px;font-size:12.5px;font-weight:700}
.mx-cmp span{flex:none;width:78px;line-height:1.2}.mx-cmp i{display:block;height:20px;border-radius:5px}.mx-cmp b{flex:none}
.mx-fr{display:flex;gap:2px;flex-wrap:wrap;justify-content:center}.mx-fr i{display:block;height:24px;flex:1 0 0;min-width:8px;max-width:60px;border-radius:4px;background:#e5e7eb;border:1px solid #d1d5db}.mx-fr i.on{background:var(--ac);border-color:var(--ac)}
.mx-people{text-align:center;font-size:20px;line-height:1.35}.mx-people span{display:block;font-size:12px;font-weight:700;color:var(--mut)}
.mx-strip{display:flex;gap:10px;align-items:center;background:#fffdf8;border:1px solid var(--line);border-radius:12px;padding:8px 10px;margin:6px 0}
.mx-sem{flex:none;font-size:26px;line-height:1.1;max-width:90px;text-align:center}
.mx-strip .mx-row{font-size:12.5px}
.mx-nv{background:#fffdf8;border:1px solid var(--line);border-radius:14px;padding:10px 8px;margin:8px 0;overflow:hidden}
.mx-nv .mx-vis{border:0;padding:0;margin:0;background:transparent}
.mx-nv .mx-cards{margin:2px 0}
.mx-ttl{font-weight:800;font-size:12.5px;text-align:center;margin-bottom:6px;color:#1f2937}
@media(max-width:380px){.mx-rn{width:66px;font-size:11.5px}.mx-head h3{font-size:14.5px}.mx-card{padding:6px}}
`;
 (function(){try{if(typeof document==='undefined'||document.getElementById('mx-m7-style'))return;const st=document.createElement('style');st.id='mx-m7-style';st.textContent=CSS;(document.head||document.documentElement).appendChild(st);}catch(e){}})();
 /* ---------- visual engines ---------- */
 const COL=['#2563eb','#f59e0b','#10b981','#ef4444','#8b5cf6','#64748b','#0ea5e9','#ec4899'];
 const T=(x,y,s,o)=>{o=o||{};return `<text x="${x}" y="${y}" text-anchor="${o.a||'middle'}" font-size="${o.s||11}" font-weight="${o.w||700}" fill="${o.f||'#1f2937'}"${o.r?` transform="rotate(${o.r} ${x} ${y})"`:''}>${esc(s)}</text>`;};
 const svg=(vb,inner,label)=>`<svg class="mx-svg" viewBox="${vb}" role="img" aria-label="${esc(label||'આકૃતિ')}">${inner}</svg>`;
 const wrap=(inner,title,cap)=>`<div class="mx-vis">${title?`<div class="mx-vt">${esc(title)}</div>`:''}${inner}${cap?`<div class="mx-cap">${fm(cap)}</div>`:''}</div>`;
 const V={};

 /* before / after cards */
 V.cards=(list,mid,title,cap)=>wrap(`<div class="mx-cards">${list.map((c,i)=>`${i?`<div class="mx-mid">${esc(mid||'⇄')}</div>`:''}<div class="mx-card ${c.b?'b':''}"><div class="mx-card-t">${esc(c.t)}</div>${c.e?`<div class="mx-ico">${icons(c.e,c.n||1,c.max||10)}</div>`:''}<div class="mx-kv">${(c.rows||[]).map(r=>`<span>${esc(r[0])}</span><b>${esc(r[1])}</b>`).join('')}</div>${c.big?`<div class="mx-big">${esc(c.big)}<small>${esc(c.bigl||'')}</small></div>`:''}</div>`).join('')}</div>`,title,cap);

 /* equal-area rectangles : height = people/machines, width = days  (man-days stay constant) */
 V.area=o=>{
  const mw=128,mh=92,top=46,x0=[14,188],cols=[COL[0],COL[1]];
  const mxw=Math.max(o.a.w,o.b.w),mxh=Math.max(o.a.h,o.b.h),sx=mw/mxw,sy=mh/mxh;
  let g='';
  [o.a,o.b].forEach((b,i)=>{
   const w=b.w*sx,h=b.h*sy,y=top+(mh-h),c=cols[i];
   g+=`<rect x="${x0[i]}" y="${y}" width="${w}" height="${h}" rx="5" fill="${c}" fill-opacity=".16" stroke="${c}" stroke-width="2.2"${b.q?' stroke-dasharray="5 3"':''}/>`;
   const nx=Math.min(b.h,8),ny=Math.min(b.w,12);
   for(let r=1;r<nx;r++)g+=`<line x1="${x0[i]}" x2="${x0[i]+w}" y1="${y+h*r/nx}" y2="${y+h*r/nx}" stroke="${c}" stroke-opacity=".18"/>`;
   for(let k=1;k<ny;k++)g+=`<line y1="${y}" y2="${y+h}" x1="${x0[i]+w*k/ny}" x2="${x0[i]+w*k/ny}" stroke="${c}" stroke-opacity=".18"/>`;
   g+=T(x0[i]+w/2,y+h/2+4,b.ar||'',{s:14,f:c,w:800});
   g+=T(x0[i],top-9,b.hl,{a:'start',s:11.5,f:c});
   g+=T(x0[i]+w/2,top+mh+16,b.wl,{s:11.5,f:c});
   g+=T(x0[i]+mw/2,12,b.t||(i?'બીજી સ્થિતિ':'પહેલી સ્થિતિ'),{s:11,f:'#6b7280'});
  });
  g+=T(165,top+mh/2+6,'=',{s:22,f:'#1f2937',w:800});
  return wrap(svg('0 0 330 182',g,'સમાન ક્ષેત્રફળના લંબચોરસ'),o.title||'કામ સરખું = ક્ષેત્રફળ સરખું',o.cap);
 };

 /* stock/ration picture : n1 people eat for d1 days; first 'used' days gone; rest re-cut as n2 x d2 */
 V.ration=o=>{
  const mw=128,mh=92,top=46,x=[14,188];
  const mxw=Math.max(o.d1,o.d2),mxh=Math.max(o.n1,o.n2),sx=mw/mxw,sy=mh/mxh;
  let g='';
  const w1=o.d1*sx,h1=o.n1*sy,y1=top+mh-h1,wu=o.used*sx;
  g+=`<rect x="${x[0]}" y="${y1}" width="${w1}" height="${h1}" rx="4" fill="#10b981" fill-opacity=".18" stroke="#10b981" stroke-width="2"/>`;
  g+=`<rect x="${x[0]}" y="${y1}" width="${wu}" height="${h1}" rx="4" fill="#9ca3af" fill-opacity=".55" stroke="#6b7280" stroke-width="1.5"/>`;
  if(wu>=36)g+=T(x[0]+wu/2,y1+h1/2+4,'વપરાયું',{s:10,f:'#374151'});
  g+=T(x[0]+wu+(w1-wu)/2,y1+h1/2+4,o.remAr||'બાકી',{s:12.5,f:'#047857',w:800});
  g+=T(x[0],top-9,o.n1l,{a:'start',s:11.5,f:'#047857'});
  g+=T(x[0]+w1/2,top+mh+16,o.d1l,{s:11,f:'#047857'});
  g+=T(x[0]+mw/2,12,o.t1||'શરૂઆતનો જથ્થો',{s:11,f:'#6b7280'});
  const w2=o.d2*sx,h2=o.n2*sy,y2=top+mh-h2;
  g+=`<rect x="${x[1]}" y="${y2}" width="${w2}" height="${h2}" rx="4" fill="#f59e0b" fill-opacity=".2" stroke="#d97706" stroke-width="2.2"${o.q?' stroke-dasharray="5 3"':''}/>`;
  g+=T(x[1]+w2/2,y2+h2/2+4,o.newAr||'બાકીનો જથ્થો',{s:12.5,f:'#b45309',w:800});
  g+=T(x[1],top-9,o.n2l,{a:'start',s:11.5,f:'#b45309'});
  g+=T(x[1]+w2/2,top+mh+16,o.d2l,{s:11,f:'#b45309'});
  g+=T(x[1]+mw/2,12,o.t2||'નવી સ્થિતિ',{s:11,f:'#6b7280'});
  g+=T(165,top+mh/2+6,'→',{s:20,f:'#1f2937',w:800});
  return wrap(svg('0 0 330 182',g,'અનાજના જથ્થાનું ચિત્ર'),o.title||'બાકી રહેલો જથ્થો એ જ રહે છે, આકાર બદલાય છે',o.cap||'રાખોડી ભાગ = ખવાઈ ગયેલો જથ્થો');
 };

 /* proportional bar */
 V.bar=o=>{const tot=o.segs.reduce((a,s)=>a+Math.abs(s.v),0)||1;return wrap(`<div class="mx-bar-wrap">${o.t?`<div class="mx-bar-t">${esc(o.t)}</div>`:''}<div class="mx-bar">${o.segs.map(s=>`<div class="mx-seg" style="flex-grow:${(Math.abs(s.v)/tot).toFixed(4)};background:${COL[s.c==null?0:s.c]}"><b>${esc(s.l||'')}</b>${s.s?`<small>${esc(s.s)}</small>`:''}</div>`).join('')}</div>${o.t2?`<div class="mx-bar-t" style="margin-top:8px">${esc(o.t2)}</div><div class="mx-bar">${o.segs2.map(s=>`<div class="mx-seg" style="flex-grow:${(Math.abs(s.v)/(o.segs2.reduce((a,z)=>a+Math.abs(z.v),0)||1)).toFixed(4)};background:${COL[s.c==null?0:s.c]}"><b>${esc(s.l||'')}</b>${s.s?`<small>${esc(s.s)}</small>`:''}</div>`).join('')}</div>`:''}</div>`,o.title,o.cap);};

 /* rate blocks per person / pipe */
 V.rates=o=>{
  const sq=(r,c)=>{const a=Math.abs(r),n=Math.floor(a),col=r<0?'#ef4444':COL[c==null?0:c];let s='';for(let i=0;i<n;i++)s+=`<i style="background:${col}"></i>`;if(a-n>=.25)s+=`<i class="h" style="background:${col}"></i>`;return s;};
  const rows=o.items.map(it=>`<div class="mx-rate"><span class="mx-rn">${it.e?esc(it.e)+' ':''}${esc(it.n)}${it.s?`<small style="display:block;font-weight:600;color:#6b7280;font-size:10.5px">${esc(it.s)}</small>`:''}</span><span class="mx-sqs">${sq(it.r,it.c)}</span><b style="color:${it.r<0?'#b91c1c':'#1f2937'}">${it.r<0?'−':''}${esc(it.rl!=null?it.rl:Math.abs(it.r))}</b></div>`).join('');
  const tot=o.tot?`<div class="mx-rate t"><span class="mx-rn">${esc(o.tot.n||'ભેગા')}</span><span class="mx-sqs">${sq(o.tot.r,5)}</span><b>${esc(o.tot.rl!=null?o.tot.rl:o.tot.r)}</b></div>`:'';
  return wrap(rows+tot+(o.foot?`<div class="mx-rf">${fm(o.foot)}</div>`:''),o.title||'એક એકમ સમયમાં થતું કામ (1 ચોરસ = 1 એકમ)',o.cap);
 };

 /* boxes joined with arrows */
 V.flow=(items,title,cap)=>wrap(`<div class="mx-flow">${items.map(x=>typeof x==='string'?(x.charAt(0)==='>'?`<div class="mx-fa">${fm(x.slice(1))}</div>`:`<div class="mx-fb">${fm(x)}</div>`):`<div class="mx-fb">${fm(x.t)}${x.s?`<small>${esc(x.s)}</small>`:''}</div>`).join('')}</div>`,title,cap);

 /* day / hour chips for repeating cycles */
 V.cycle=o=>wrap(`<div class="mx-cycle">${o.cells.map(c=>c.gap?`<div class="mx-cgap">${esc(c.gap)}</div>`:`<div class="mx-cc" style="--cc:${COL[c.c==null?0:c.c]}"><small>${esc(c.d||'')}</small><b>${esc(c.l)}</b><span>${esc(c.u)}</span>${c.run!=null?`<em>કુલ ${esc(c.run)}</em>`:''}</div>`).join('')}</div>`,o.title||'દિવસ પ્રમાણે કામ',o.cap);

 /* tank picture with inlets (top) and outlets (right) */
 V.tank=o=>{
  const tx=70,tw=150,ty=58,th=96,lv=clamp(o.level==null?0.5:o.level,0,1);
  let g='';
  const wh=th*lv;
  g+=`<rect x="${tx}" y="${ty+th-wh}" width="${tw}" height="${wh}" fill="#7dd3fc" fill-opacity=".75"/>`;
  g+=`<path d="M${tx} ${ty}V${ty+th}H${tx+tw}V${ty}" fill="none" stroke="#334155" stroke-width="5" stroke-linejoin="round"/>`;
  if(o.mark!=null){const my=ty+th-th*o.mark;g+=`<line x1="${tx}" x2="${tx+tw}" y1="${my}" y2="${my}" stroke="#0f172a" stroke-dasharray="4 3"/>`+T(tx+tw-4,my-3,o.markl||'',{a:'end',s:10,f:'#0f172a'});}
  g+=T(tx+tw/2,ty+th/2+(lv>.45?-4:4),o.mid||'ટાંકી',{s:12,f:'#0c4a6e'});
  const ins=o.ins||[],outs=o.outs||[];
  ins.forEach((p,i)=>{const x=ins.length===1?tx+tw/2:tx+28+i*((tw-56)/(ins.length-1));g+=`<line x1="${x}" x2="${x}" y1="30" y2="${ty-2}" stroke="#10b981" stroke-width="7" stroke-linecap="round"/><path d="M${x-7} ${ty-12}L${x} ${ty}L${x+7} ${ty-12}" fill="none" stroke="#10b981" stroke-width="3.5"/>`+T(x,11,p.l,{s:11.5,f:'#047857'})+T(x,24,p.s||'',{s:10.5,f:'#047857',w:800});});
  outs.forEach((p,i)=>{const y=ty+th-24-i*30;g+=`<line x1="${tx+tw}" x2="${tx+tw+62}" y1="${y}" y2="${y}" stroke="#ef4444" stroke-width="7" stroke-linecap="round"/><path d="M${tx+tw+50} ${y-8}L${tx+tw+64} ${y}L${tx+tw+50} ${y+8}" fill="none" stroke="#ef4444" stroke-width="3.5"/>`+T(tx+tw+66,y-8,p.l,{a:'start',s:11,f:'#b91c1c'})+T(tx+tw+66,y+17,p.s||'',{a:'start',s:9.5,f:'#b91c1c'});});
  if(o.left)g+=o.left;
  g+=T(165,177,o.net||'',{s:12,f:'#0f172a',w:800});
  return wrap(svg('0 0 330 184',g,'ટાંકી અને પાઇપની આકૃતિ'),o.title,o.cap);
 };

 /* tyre with punctures */
 V.tyre=o=>{
  let g=`<circle cx="165" cy="84" r="62" fill="#374151"/><circle cx="165" cy="84" r="38" fill="#e5e7eb"/>`;
  const pos=[[212,50,265,26,'start'],[212,118,265,142,'start']];
  const pos2=[[118,50,66,26,'end'],[118,118,66,142,'end']];
  o.holes.forEach((h,i)=>{const p=(o.holes.length===2?(i?pos2[1]:pos[0]):pos[0]);const [hx,hy,tx,ty,an]=p;g+=`<circle cx="${hx}" cy="${hy}" r="5" fill="#fbbf24" stroke="#000" stroke-width="1"/><path d="M${hx} ${hy}L${tx} ${ty}" stroke="#ef4444" stroke-width="3" stroke-dasharray="5 4"/>`+T(tx,ty-6,'💨 '+h.l,{a:an,s:11.5,f:'#b91c1c'})+T(tx,ty+8,h.s||'',{a:an,s:10,f:'#6b7280'});});
  g+=T(165,88,o.mid||'ટાયર',{s:11,f:'#374151'});
  return wrap(svg('0 0 330 168',g,'ટાયરમાં બે પંક્ચર'),o.title||'હવા બહાર નીકળે = ટાંકી ખાલી થાય',o.cap);
 };

 /* triangle of pair-sums */
 V.pairs=o=>{
  const pts=[[165,34],[52,140],[278,140]];
  let g='';
  o.edges.forEach(e=>{const a=pts[e[0]],b=pts[e[1]];g+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#94a3b8" stroke-width="3"/>`;const mx=(a[0]+b[0])/2,my=(a[1]+b[1])/2;g+=`<rect x="${mx-34}" y="${my-11}" width="68" height="22" rx="11" fill="#fff" stroke="${COL[e[4]==null?0:e[4]]}" stroke-width="2"/>`+T(mx,my+4,e[2]+' = '+e[3],{s:11,f:COL[e[4]==null?0:e[4]]});});
  o.names.forEach((n,i)=>{const p=pts[i];g+=`<circle cx="${p[0]}" cy="${p[1]}" r="22" fill="${COL[i]}"/>`+T(p[0],p[1]+(o.vals?-1:5),n,{s:14,f:'#fff',w:800});if(o.vals)g+=T(p[0],p[1]+12,o.vals[i],{s:10.5,f:'#fff'});});
  g+=T(165,118,o.center||'',{s:11,f:'#1f2937',w:800});
  return wrap(svg('0 0 330 172',g,'જોડીના સરવાળાનો ત્રિકોણ'),o.title||'ત્રણે જોડી ઉમેરો → દરેકની ક્ષમતા બે વખત ગણાય',o.cap);
 };

 /* see-saw for algebra */
 V.balance=o=>{
  let g=`<path d="M165 62L145 118H185Z" fill="#94a3b8"/><rect x="28" y="56" width="274" height="8" rx="4" fill="#475569"/>`;
  [[40,o.l],[190,o.r]].forEach(([x,b],i)=>{const c=COL[i?1:0];g+=`<line x1="${x+14}" y1="62" x2="${x+14}" y2="76" stroke="#475569" stroke-width="2"/><line x1="${x+86}" y1="62" x2="${x+86}" y2="76" stroke="#475569" stroke-width="2"/><rect x="${x-2}" y="76" width="104" height="52" rx="10" fill="${c}" fill-opacity=".14" stroke="${c}" stroke-width="2"/>`+T(x+50,98,b.t,{s:13,f:c,w:800})+T(x+50,116,b.s||'',{s:10.5,f:'#475569'});});
  g+=T(165,48,'=',{s:20,f:'#1f2937',w:800});
  g+=T(90,24,o.lt||'પહેલાનું કુલ કામ',{s:11,f:'#6b7280'})+T(240,24,o.rt||'પછીનું કુલ કામ',{s:11,f:'#6b7280'});
  return wrap(svg('0 0 330 140',g,'બંને બાજુ સમાન કામ'),o.title||'કુલ કામ બંને બાજુ સરખું',o.cap);
 };

 /* horizontal comparison bars */
 V.compare=o=>{const mx=Math.max.apply(null,o.items.map(i=>i.v));return wrap(`<div class="mx-cmp">${o.items.map(i=>`<div><span>${esc(i.l)}</span><i style="width:${(i.v/mx*100).toFixed(1)}%;background:${COL[i.c==null?0:i.c]}"></i><b>${esc(i.t!=null?i.t:i.v)}</b></div>`).join('')}</div>`,o.title,o.cap);};

 /* simple table */
 V.table=o=>wrap(`<table class="mx-tbl"><tr>${o.head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr>${o.rows.map((r,i)=>`<tr class="${i===o.hi?'hi':''}">${r.map(c=>`<td>${fm(String(c))}</td>`).join('')}</tr>`).join('')}</table>`,o.title,o.cap);

 /* true/false statements */
 V.verdicts=(list,title)=>wrap(`<div class="mx-vd">${list.map(x=>`<div class="${x.ok?'y':'n'}"><b class="m">${x.ok?'✅':'❌'}</b><span>${fm(x.t)}</span></div>`).join('')}</div>`,title);

 /* fraction blocks */
 V.frac=o=>wrap(`<div class="mx-fr">${Array.from({length:o.d},(_,i)=>`<i class="${i<o.n?'on':''}"></i>`).join('')}</div>`,o.title,o.cap);

 /* emoji row */
 V.people=(e,n,label,title)=>wrap(`<div class="mx-people">${icons(e,n,16)}<span>${esc(label)}</span></div>`,title);
 /* ---------- solution renderer ---------- */
 const SPEC={chain:{},work:{},pipes:{}};
 const Q=(k,n,s)=>{SPEC[k][n]=s;};
 const stepHtml=(st,i)=>{
  let t=st[0],lines=st.slice(1),hd=true;
  if(t.charAt(0)==='>'||t.charAt(0)==='~'){lines=[t].concat(lines);hd=false;}
  return `<div class="mx-step"><span class="mx-no">${i+1}</span><div class="mx-sb">${hd?`<h4>${fm(t)}</h4>`:''}${lines.map(l=>{const c=l.charAt(0);if(c==='~')return `<div class="mx-eq">${fm(l.slice(1))}</div>`;if(c==='>')return `<div class="mx-res">${fm(l.slice(1))}</div>`;return `<p>${fm(l)}</p>`;}).join('')}</div></div>`;
 };
 function linesOf(exp){return String(exp||'').replace(/\r/g,'').split(/\n+/).map(s=>s.trim()).filter(Boolean);}
 function fallbackSpec(q){
  const L=linesOf(q.explanation);
  return {em:'📝',given:[],find:'',idea:'',vis:[],st:[['ઉકેલ'].concat(L.map((x,i)=>i===L.length-1?'>'+x:'~'+x))],ans:''};
 }
 function solutionHtml(ch,q,sourceTitle,no,opts,ai,sp){
  sp=sp||fallbackSpec(q);
  const letter='ABCD'[ai]||'?';
  const ansTxt=sp.ans||opts[ai]||'';
  const given=(sp.given||[]).length?`<div class="mx-row"><label>📌 આપેલું</label>${sp.given.map(g=>`<span class="mx-pill">${fm(g)}</span>`).join('')}</div>`:'';
  const find=sp.find?`<div class="mx-row"><label>🎯 શોધવાનું</label><span class="mx-pill f">${fm(sp.find)}</span></div>`:'';
  const optHtml=opts.map((o,i)=>`<span class="mx-opt ${i===ai?'ok':''}">${'ABCD'[i]||i+1}) ${esc(o)}</span>`).join('');
  return `<section class="mx-sol mx-c-${ch}"><div class="mx-head"><div><small>${subMap[ch]} · પ્રશ્ન ${no}</small><h3>${esc(q.topic||titleMap[ch])}</h3></div><div class="mx-qno">${String(no).padStart(2,'0')}<small>Q</small></div></div>`
   +`<div class="mx-gf">${given}${find}</div>`
   +(sp.idea?`<div class="mx-idea"><span>💡</span><div>${fm(sp.idea)}</div></div>`:'')
   +(sp.vis||[]).join('')
   +(sp.note?`<div class="mx-note">⚠️ ${fm(sp.note)}</div>`:'')
   +`<div class="mx-steps">${(sp.st||[]).map(stepHtml).join('')}</div>`
   +`<div class="mx-ans"><b>✓</b><div><small>સાચો જવાબ · વિકલ્પ ${letter}</small><strong>${fm(ansTxt)}</strong></div></div>`
   +`<div class="mx-opts">${optHtml}</div>`
   +(sp.chk?`<div class="mx-chk"><span>🔁</span><div><b>ચકાસણી:</b> ${fm(sp.chk)}</div></div>`:'')
   +(sp.tip?`<div class="mx-tip"><span>⚡</span><div><b>શોર્ટકટ:</b> ${fm(sp.tip)}</div></div>`:'')
   +(sp.trap?`<div class="mx-trap"><span>⚠️</span><div><b>ધ્યાન રાખો:</b> ${fm(sp.trap)}</div></div>`:'')
   +`</section>`;
 }
 function compactVisual(ch,q,sp){
  sp=sp||{};
  const g=(sp.given||[]).slice(0,5).map(x=>`<span class="mx-pill">${fm(x)}</span>`).join('');
  const f=sp.find?`<span class="mx-pill f">🎯 ${fm(sp.find)}</span>`:'';
  return `<div class="mx-strip mx-c-${ch}"><div class="mx-sem">${esc(sp.em||'🧮')}</div><div class="mx-row">${g}${f}</div></div>`;
 }
